entries[1233539] = { ["name"] = "Verschlingen", ["text"] = "Wirken in 2 sek.\nSobald er 100 Energie erreicht, erhöht Dimensius seine Dichte und erschafft eine mächtige, nach innen gerichtete Kraft, die 5 Sek. lang alle 1 Sek. 1686460 Schattenschaden verursacht und Spielercharaktere, Leerensterne, Schwarze Löcher und die Akkretionsscheibe hineinzieht.\n\nNach 5 Sek. wird jeder Spielercharakter außerhalb von ' Gravitationsbrunnen ' eines Leerensterns sofort in Dimensius hineingesogen und fällt ins ' Auslöschung '." }
entries[1233542] = { ["name"] = "Der Knochengefrierer", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Dieser Kriecher ist ein erbitterter Rivale des Knochenschmelzers und wurde nach einer vernichtenden Niederlage aus seinem Versteck in der Manaschmiede Omega vertrieben. Jetzt will er von demjenigen lernen, der seinen größten Feind entthront hat.\"\nVandalen der Manaschmiede\nRuhmstufe:\n14\nOrt:\nSchattenpunkt" }
entries[1233544] = { ["name"] = "Erzählstundenteppich beschwören" }
entries[1233546] = { ["name"] = "Rubinroter Leerenkrabbler", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Dieser Leerenkrabbler wurde vom Bund von K'aresh für Forschungszwecke \"gerettet\". Er hat sich als überaus robustes Reittier erwiesen.\"\nVerkäufer:\nOm'sirik\nZone:\nK'aresh\nKosten:\n8.125" }
entries[1233547] = { ["name"] = "Ätzender Leerenkrabbler", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Dieser Krabbler hat sich an giftigen Dünsten gelabt, wodurch sein Körper mit mächtigen Säuren angereichert wurde.\"\nVerkäufer:\nShad'anis\nZone:\nK'aresh\nKosten:\n7" }
entries[1233548] = { ["name"] = "Erzählstundenteppich freigeben" }
entries[1233553] = { ["name"] = "Unnachgiebiges Netherprisma", ["text"] = "Eure Fähigkeiten, die Schaden zufügen, ziehen fokussierte Leere aus dem Prisma, um ( 441 * 1 ) kosmischen Schaden zu verursachen, der zwischen Eurem Ziel und nahen Gegnern aufgeteilt wird. Der Schaden erhöht sich pro getroffenem Gegner um 30%, bis insgesamt 150%. Dieser Effekt kann alle 10 Sek. auftreten und sammelt bis zu 18 Mal die latente Macht innerhalb des Prismas.\n(10s Abklingzeit)" }
entries[1233556] = { ["name"] = "Unnachgiebiges Netherprisma", ["text"] = "Sofort 20 sek. Abklingzeit\nVerbraucht sämtliche latente Macht, um 20 Sek. lang 18 Stärke oder Beweglichkeit pro Stapel zu erhalten." }
entries[1233557] = { ["name"] = "Dichte", ["text"] = "Sofort\nErhöht den Schaden von 'Kosmische Strahlung' um 100%. Dieser Effekt ist stapelbar." }
entries[1233559] = { ["name"] = "Blauer Ingmar", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Eine besonders seltene Variante der Schieferrücken. Der \"Blaue Ingmar\" wurde zuvor beim Transport von Lasten eingesetzt.\"\nQuest:\nEuer Blauer\nZone:\nK'aresh" }
entries[1233561] = { ["name"] = "Neugieriger Schieferrücken", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Dieser neugierige Schieferrücken hat es irgendwie geschafft, in einer Kiste steckenzubleiben. Wie er es da überhaupt reingeschafft hat, ist noch nicht geklärt.\"\nBeute:\nZuckende Kiste des Gipfels\nZone:\nK'aresh" }
