entries[1233592] = { ["name"] = "Schrecken aus der Tiefe", ["text"] = "Ca. 5 Procs pro Minute\nEure Fähigkeiten ziehen regelmäßig ein Ungetüm aus der Tiefe an, das Euren Gegner sucht und [(440% Angriffs-/Zaubermacht)] Naturschaden verursacht, der gleichmäßig auf alle Gegner in der Nähe des Ziels aufgeteilt wird.\n\nWenn der ' Schrecken aus der Tiefe ' einen Gegner mit ' Teufelsberührt ' trifft, verursacht er ' Tiefensogschmettern ' und fügt allen Gegnern in der Nähe [(440% Angriffs-/Zaubermacht)] Naturschaden zu." }
entries[1233594] = { ["name"] = "Schrecken aus der Tiefe", ["text"] = "30 Meter Reichweite\nSofort\nEure Fähigkeiten ziehen regelmäßig ein Ungetüm aus der Tiefe an, das Euren Gegner sucht und [(440% Angriffs-/Zaubermacht)] Naturschaden verursacht, der gleichmäßig auf alle Gegner in der Nähe des Ziels aufgeteilt wird.\n\nWenn der ' Schrecken aus der Tiefe ' einen Gegner mit ' Teufelsberührt ' trifft, verursacht er ' Tiefensogschmettern ' und fügt allen Gegnern in der Nähe [(440% Angriffs-/Zaubermacht)] Naturschaden zu." }
entries[1233595] = { ["name"] = "Schrecken aus der Tiefe", ["text"] = "100 Meter Reichweite\nSofort\nEure Fähigkeiten ziehen regelmäßig ein Ungetüm aus der Tiefe an, das Euren Gegner sucht und [(440% Angriffs-/Zaubermacht)] Naturschaden verursacht, der gleichmäßig auf alle Gegner in der Nähe des Ziels aufgeteilt wird.\n\nWenn der ' Schrecken aus der Tiefe ' einen Gegner mit ' Teufelsberührt ' trifft, verursacht er ' Tiefensogschmettern ' und fügt allen Gegnern in der Nähe [(440% Angriffs-/Zaubermacht)] Naturschaden zu." }
entries[1233596] = { ["name"] = "Schrecken aus der Tiefe", ["text"] = "100 Meter Reichweite\nSofort\nEure Distanzangriffe und Zauber haben eine Chance, ein Ungetüm aus der Tiefe zu beschwören, das Euer Ziel in einem Stück verschlingt und so 4064 Naturschaden verursacht, der auf Euch und alle Gegner in der Nähe aufgeteilt wird." }
