entries[1233613] = { ["name"] = "Xe'ras Umarmung", ["text"] = "Xe'ra wacht über Euch. Wenn Eure Gesundheit unter 40% fällt, empfangt Ihr ihre Umarmung und werdet ' Lichtgeschmiedet ', wodurch der erlittene Schaden 8 Sek. lang um 80% verringert wird. Kann nur einmal alle 1.5 Min. auftreten.\n\nLichtgeschmiedet\nErmächtigt die anderen Lichtboni Eures Artefakts.\n(1s Abklingzeit)" }
