entries[1233654] = { ["name"] = "Managetönte Brille", ["text"] = "Unbegrenzte Reichweite\nSofort\nBrann setzt während des Kampfes eine managetönte Brille auf, die alle 5 Sek. seinen verursachten Schaden um 4% und seinen erlittenen Schaden um 5% erhöht, bis zu 10-mal.\n\nWird die Brille gebannt, heilt Brann sich um 40% seiner maximalen Gesundheit und betäubt Gegner in der Nähe für 3 Sek.\nAndernfalls wird dieser Effekt automatisch gebannt, wenn Branns Gesundheit unter 30% sinkt, wodurch die Betäubung verhindert wird." }
entries[1233655] = { ["name"] = "Managetönte Brille", ["text"] = "Unbegrenzte Reichweite\nSofort\nBrann setzt während des Kampfes eine managetönte Brille auf, die alle 5 Sek. seinen verursachten Schaden um 5% und seinen erlittenen Schaden um 5% erhöht, bis zu 10-mal.\n\nWird die Brille gebannt, heilt Brann sich um 55% seiner maximalen Gesundheit und betäubt Gegner in der Nähe für 4 Sek.\nAndernfalls wird dieser Effekt automatisch gebannt, wenn Branns Gesundheit unter 30% sinkt, wodurch die Betäubung verhindert wird." }
entries[1233656] = { ["name"] = "Managetönte Brille", ["text"] = "Unbegrenzte Reichweite\nSofort\nBrann setzt während des Kampfes eine managetönte Brille auf, die alle 5 Sek. seinen verursachten Schaden um 5% und seinen erlittenen Schaden um 5% erhöht, bis zu 10-mal.\n\nWird die Brille gebannt, heilt Brann sich um 70% seiner maximalen Gesundheit und betäubt Gegner in der Nähe für 5 Sek.\nAndernfalls wird dieser Effekt automatisch gebannt, wenn Branns Gesundheit unter 30% sinkt, wodurch die Betäubung verhindert wird." }
entries[1233657] = { ["name"] = "Netherprisma", ["text"] = "Sofort\nSechs dunkle Kristalle geben ' Refraktierte Entropie ' in einer Linie auf Fraktillus zu ab, was Spielercharakteren bei Berührung alle 0.5 Sek. 703583 Schattenschaden zufügt." }
entries[1233659] = { ["name"] = "Hatarang", ["text"] = "100 Meter Reichweite\nSofort\nCa. 2 Procs pro Minute\nBrann hat eine Chance, zufällig ausgewählte Hüte hervorzuziehen und sie auf seine Gegner zu werfen, wodurch er mäßigen Schaden verursacht und 1 Schwächungseffekt auf 3 Ziele anwendet.\n\nMögliche Schwächungseffekte sind eine Erhöhung des erlittenen Schadens um 25%, eine Verringerung des verursachten Schadens um 25% sowie eine Verringerung des Angriffs- und Zaubertempos um 25%.\n(20s Abklingzeit)" }
entries[1233660] = { ["name"] = "Hatarang", ["text"] = "100 Meter Reichweite\nSofort\nCa. 2 Procs pro Minute\nBrann hat eine Chance, zufällig ausgewählte Hüte hervorzuziehen und sie auf seine Gegner zu werfen, wodurch er mäßigen Schaden verursacht und 2 Schwächungseffekte auf 4 Ziele anwendet.\n\nMögliche Schwächungseffekte sind eine Erhöhung des erlittenen Schadens um 30%, eine Verringerung des verursachten Schadens um 30% sowie eine Verringerung des Angriffs- und Zaubertempos um 30%.\n(20s Abklingzeit)" }
