entries[1233693] = { ["name"] = "Sande von K'aresh", ["text"] = "Unbegrenzte Reichweite\nSofort\nWenn Brann ' Sammelwerkzeuge ' einsetzt, beginnen Sande um die Gruppenmitglieder zu wirbeln, gewähren bis zu 10-mal 8% kritischen Trefferwert und verlangsamen Gegner in der Nähe um 8%.\n\nEin kritischer Treffer erschafft 6 Sek. lang einen Sandteufel am Ort des Ziels, der Gegner periodisch in sein Zentrum zieht. Kann nur alle 45 Sek. auftreten.\n\nSammelwerkzeuge\nBrann setzt seine Sammelwerkzeuge ein, um Spielercharakteren zu helfen, zusätzliches Gold, Erz, Leder, zusätzliche Kräuter, Fische und Schätze zu finden." }
entries[1233694] = { ["name"] = "Sande von K'aresh", ["text"] = "Unbegrenzte Reichweite\nSofort\nWenn Brann ' Sammelwerkzeuge ' einsetzt, beginnen Sande um die Gruppenmitglieder zu wirbeln, gewähren bis zu 10-mal 10% kritischen Trefferwert und verlangsamen Gegner in der Nähe um 10%.\n\nEin kritischer Treffer erschafft 6 Sek. lang einen Sandteufel am Ort des Ziels, der Gegner periodisch in sein Zentrum zieht. Kann nur alle 45 Sek. auftreten.\n\nSammelwerkzeuge\nBrann setzt seine Sammelwerkzeuge ein, um Spielercharakteren zu helfen, zusätzliches Gold, Erz, Leder, zusätzliche Kräuter, Fische und Schätze zu finden." }
entries[1233695] = { ["name"] = "Sande von K'aresh", ["text"] = "Unbegrenzte Reichweite\nSofort\nWenn Brann ' Sammelwerkzeuge ' einsetzt, beginnen Sande um die Gruppenmitglieder zu wirbeln, gewähren bis zu 10-mal 12% kritischen Trefferwert und verlangsamen Gegner in der Nähe um 12%.\n\nEin kritischer Treffer erschafft 6 Sek. lang einen Sandteufel am Ort des Ziels, der Gegner periodisch in sein Zentrum zieht. Kann nur alle 45 Sek. auftreten.\n\nSammelwerkzeuge\nBrann setzt seine Sammelwerkzeuge ein, um Spielercharakteren zu helfen, zusätzliches Gold, Erz, Leder, zusätzliche Kräuter, Fische und Schätze zu finden." }
entries[1233699] = { ["name"] = "Äthernova", ["text"] = "100 Meter Reichweite\nSofort\nWenn die Gesundheit eines Gruppenmitglieds unter 60 % sinkt, materialisiert sich ein astraler Energieumwandler, der Gegnern in der Nähe moderaten Schaden zufügt und diese 4 Sek. lang verspottet. Nach Ablauf des Spotts entfesselt der Umwandler eine Ätherwelle, die Verbündete in der Nähe um 30 % ihrer Gesundheit heilt. Kann alle 2 Min. ausgelöst werden. Das Töten von Gegnern reduziert die Abklingzeit dieses Effekts um 4 Sek." }
entries[1233700] = { ["name"] = "Äthernova", ["text"] = "100 Meter Reichweite\nSofort\nWenn die Gesundheit eines Gruppenmitglieds unter 60 % sinkt, materialisiert sich ein astraler Energieumwandler, der Gegnern in der Nähe moderaten Schaden zufügt und diese 6 Sek. lang verspottet. Nach Ablauf des Spotts entfesselt der Umwandler eine Ätherwelle, die Verbündete in der Nähe um 40 % ihrer Gesundheit heilt. Kann alle 2 Min. ausgelöst werden. Das Töten von Gegnern reduziert die Abklingzeit dieses Effekts um 6 Sek." }
entries[1233701] = { ["name"] = "Äthernova", ["text"] = "100 Meter Reichweite\nSofort\nWenn die Gesundheit eines Gruppenmitglieds unter 60 % sinkt, materialisiert sich ein astraler Energieumwandler, der Gegnern in der Nähe moderaten Schaden zufügt und diese 6 Sek. lang verspottet. Nach Ablauf des Spotts entfesselt der Umwandler eine Ätherwelle, die Verbündete in der Nähe um 50 % ihrer Gesundheit heilt. Kann alle 2 Min. ausgelöst werden. Das Töten von Gegnern reduziert die Abklingzeit dieses Effekts um 8 Sek." }
entries[1233702] = { ["name"] = "Bezwingen", ["text"] = "Unbegrenzte Reichweite\nSofort\nSalhadaar spaltet sein aktuelles Ziel und fügt allen Spielercharakteren vor sich 22486129 körperlichen Schaden und zusätzlich 35415654 Schattenschaden zu, wobei diese weggestoßen werden.\n\nErhöht den durch ' Bezwingen ' erlittenen Schaden 20 Sek. lang um 500%." }
