entries[1233775] = { ["name"] = "Narans Immerscheibe", ["text"] = "40 Meter Reichweite\nSofort 1 min Abklingzeit\nArtefaktfähigkeit\n\nWirft eine Scheibe arkaner Energie, die einen Bogen beschreibt, bevor sie zu Euch zurückkehrt.\n\n' Narans Immerscheibe ' fügt allen Gegnern in ihrem Weg [(1930% Angriffs-/Zaubermacht)] Arkanschaden zu.\n\nFangt das Projektil ab, um es bis zu 5-mal erneut werfen zu können, wobei sich der Schaden mit jedem Wurf in Folge um 60% erhöht." }
