entries[1233894] = { ["name"] = "Rückenwindleiter", ["text"] = "Unbegrenzte Reichweite\nSofort\nVerleiht beim Verlassen des Kampfes einen Geschwindigkeitsschub, der Eure Bewegungsgeschwindigkeit 10 Sek. lang um 60% erhöht. Nimmt mit der Zeit ab. Wenn Ihr im Kampf eine Defensivfähigkeit einsetzt, werdet Ihr von Windstößen eingehüllt, die Euch 8 Sek. lang einen Schild in Höhe von 30% Eurer verlorenen Gesundheit verleihen.\n(30s Abklingzeit)" }
entries[1233895] = { ["name"] = "Audioverstärkungskristall", ["text"] = "Unbegrenzte Reichweite\nSofort\nBranns Stimme wird durch arkane Magie etwas verstärkt, wodurch seine Worte der Gruppe je nach Gesagtem einen Stärkungseffekt verleihen können." }
entries[1233896] = { ["name"] = "Ramponierte Aegis", ["text"] = "Unbegrenzte Reichweite\nSofort\nWährend die Aegis ausgerüstet ist, verursachen alle Gruppenmitglieder 6% mehr Schaden und Heilung. Im Kampf heilt Ihr und Brann alle 10 Sek. um 10% des Schadens, den Ihr in dieser Zeit erlitten habt.\n\nStirbt ein Spielercharakter, gewährt die Aegis diesem bei der Wiederbelebung 2% Schadensverringerung und 3% erhöhte Heilung, reduziert jedoch seinen verursachten Schaden und die Heilung um 2%. Dieser Effekt ist bis zu 3-mal stapelbar." }
entries[1233897] = { ["name"] = "Temporalentschleunigungskristall", ["text"] = "Unbegrenzte Reichweite\nSofort\nWenn Ihr einem Elitegegner mit 80% oder mehr sowie mit 20% oder weniger Gesundheit Schaden zufügt, löst Brann die Energien des Kristalls aus. Dies verringert das Angriffs- und Zaubertempo des Elitegegners 30 Sek. lang um 30%. Wird der betroffene Elitegegner getötet, während der Schwächungseffekt aktiv ist, erhält die Gruppe eine stapelbare Tempostärkung von 4%." }
entries[1233898] = { ["name"] = "Sonderbares Gerät", ["text"] = "Unbegrenzte Reichweite\nSofort\nCa. 2 Procs pro Minute\nBrann hat eine Chance, Spielercharakteren 20 Sek. lang und basierend auf seiner gewählten Kampfrolle einen Bonus von 10% auf Gesundheit, Schaden oder Heilung zu gewähren.\n\nSpielercharaktere haben eine Chance, Brann 20 Sek. lang und basierend auf ihrer gewählten Rolle einen Bonus von 10% auf Gesundheit, Schaden oder Heilung zu gewähren.\n(20s Abklingzeit)" }
entries[1233899] = { ["name"] = "Astraler Energieumwandler", ["text"] = "Unbegrenzte Reichweite\nSofort\nWenn die Gesundheit eines Gruppenmitglieds unter 60% sinkt, materialisiert sich ein astraler Energieumwandler, der Gegnern in der Nähe moderaten Schaden zufügt und diese 4 Sek. lang verspottet. Nach Ablauf des Spotts entfesselt der Umwandler eine Ätherwelle, die Verbündete in der Nähe um 30% ihrer Gesundheit heilt. Kann alle 2 Min. ausgelöst werden. Das Töten von Gegnern reduziert die Abklingzeit dieses Effekts um 4 Sek." }
