entries[1234283] = { ["name"] = "Narans Immerscheibe", ["text"] = "Artefaktfähigkeit\n\nWirft eine Scheibe arkaner Energie, die einen Bogen beschreibt, bevor sie zu Euch zurückkehrt.\n\n' Narans Immerscheibe ' fügt allen Gegnern in ihrem Weg [(1930% Angriffs-/Zaubermacht)] Arkanschaden zu.\n\nFangt das Projektil ab, um einen Absorptionsschild zu erhalten und es bis zu 2-mal erneut werfen zu können." }
