entries[1234529] = { ["name"] = "Kosmischer Schlund", ["text"] = "Unbegrenzte Reichweite\nWirken in 1.25 sek.\nDie Leerenschwinge zerfetzt ihr aktuelles Ziel mit stellaren Lefzen und verursacht 112430647 körperlichen Schaden.\n\nDie Essenz des Ziels wird verschlungen, was zusätzlich alle 0.3 Sek. 4216149 kosmischen Schaden verursacht und den durch ' Dimensionsatem ' erlittenen Schaden 10 Sek. lang um 200% erhöht." }
entries[1234531] = { ["name"] = "Energiegeladen", ["text"] = "Sofort\nEin Schub drakonischer Energie ist aktiv." }
entries[1234532] = { ["name"] = "Tiefsitzende Stärke", ["text"] = "Sofort\nBlut\nWenn 'Vampirstoß' einem Gegner Schaden zufügt, der mit Eurer Blutseuche belegt ist, wird die Krankheit um 3 Sek. verlängert und der Gegner erleidet 10% des verbleibenden Schadens.\n\nWenn 'Gabe der San'layn' endet, wird die Abklingzeit von 'Tod und Verfall' und Euer nächster Einsatz von 'Herzstoß' verbraucht die Krankheit und fügt dem Ziel 100% des verbleibenden Schadens zu.\n\nUnheilig\nWenn 'Vampirstoß' einem Gegner Schaden zufügt, der mit Eurer Virulenten Seuche belegt ist, wird die Krankheit um 3 Sek. verlängert und der Gegner erleidet 10% des verbleibenden Schadens.\n\nWenn 'Gabe der San'layn' endet, wird die Abklingzeit von 'Tod und Verfall' und Euer nächster Einsatz von verbraucht die Krankheit und fügt dem Ziel 100% des verbleibenden Schadens zu.\n(1s Abklingzeit)" }
entries[1234533] = { ["name"] = "Kosmischer Schlund", ["text"] = "Unbegrenzte Reichweite\nSofort\nDie Leerenschwinge zerfetzt ihr aktuelles Ziel mit stellaren Lefzen und verursacht 112430647 körperlichen Schaden.\n\nDie Essenz des Ziels wird verschlungen, was zusätzlich alle 0.3 Sek. 4216149 kosmischen Schaden verursacht und den durch ' Dimensionsatem ' erlittenen Schaden 10 Sek. lang um 200% erhöht." }
