entries[1234547] = { ["name"] = "Einkerkern", ["text"] = "Unbegrenzte Reichweite\nSofort\nIlyssa kerkert mehrere Spielercharaktere ein, indem sie ein Gefängnis manifestiert, das Ziele in seinem Inneren festwurzelt und Spielercharakteren innerhalb von 3 Metern um den Einschlagsort 25 Chaosschaden zufügt.\n\nDieses Gefängnis verursacht alle 1 Sek. 7 Chaosschaden und macht seine Insassen bewegungsunfähig, bis es zerstört wird." }
entries[1234558] = { ["name"] = "Flammenstich", ["text"] = "15 Meter Reichweite\nWirken in 1.35 sek.\nTrifft den Gegner mit Flammen und fügt ihm 14 Sek. lang alle 2 Sek. Feuerschaden zu. Dieser Effekt nimmt mit der Zeit ab." }
entries[1234559] = { ["name"] = "Entweihen", ["text"] = "'Tod und Verfall' verursacht 100% mehr Schaden. Die Abklingzeit wird um 10 Sek. reduziert und nach dem Wirken durch 'Entweihung' ersetzt.\n\nEntweihen\nVerbraucht 'Tod und Verfall' und zerschmettert Eure Gegner darin, was ihnen 100% des verbleibenden Schadens sofort zufügt. Wendet 1-2 'Schwärende Wunden' an oder lässt sie aufbrechen, je nachdem, ob das Ziel bereits von 'Schwärende Wunden' betroffen ist.\n\nVerleiht Euch die Boni, als würdet Ihr Euch im Wirkungsbereich von 'Tod und Verfall' aufhalten." }
