entries[1234563] = { ["name"] = "Wirbelnder Abgrund", ["text"] = "Unbegrenzte Reichweite\nKanalisiert (Wirken in 14 sek.)\nAdarus öffnet einen Riss zur Leere, der allen Spielercharakteren 14 Sek. lang alle 2 Sek. 30 kosmischen Schaden zufügt.\n\nDie ersten 3 Spielercharaktere, die den Riss betreten, erhalten ' Zorn des Verschlingers '." }
entries[1234565] = { ["name"] = "Verschlingen", ["text"] = "Unbegrenzte Reichweite\nWirken in 2 sek.\nAdarus entzieht Spielercharakteren die Essenz, die von ' Zorn des Verschlingers ' betroffen sind, verursacht 667557 kosmischen Schaden und absorbiert die nächste 2305797 erhaltene Heilung.\n\nDieser Ausbruch ruft ' Endloser Hunger ' hervor." }
