entries[1234817] = { ["name"] = "Galaktisches Schmettern", ["text"] = "Unbegrenzte Reichweite\nSofort\nNeben Salhadaar selbst erscheinen Abbilder von ihm, die ihre Ziele mit galaktischer Kraft zerschmettern, alle Spielercharaktere mit ' Zwielichtnarbe ' belegen und ihnen 56 kosmischen Schaden zufügen. Spielercharaktere, die weiter von den einzelnen Zielen entfernt sind, erleiden weniger Schaden.\n\nSalhadaars Primärziel ist ' Sternenzerschmettert '. An jedem Einschlagsort entsteht ' Dunkler Stern '." }
