entries[1235158] = { ["name"] = "Verschlingen", ["text"] = "Unbegrenzte Reichweite\nSofort\nAdarus entzieht Spielercharakteren die Essenz, die von ' Zorn des Verschlingers ' betroffen sind, verursacht 667557 kosmischen Schaden und absorbiert die nächste 2305797 erhaltene Heilung.\n\nDieser Ausbruch ruft ' Endloser Hunger ' hervor." }
entries[1235159] = { ["name"] = "Seelen des Krächzens", ["text"] = "Ca. 4 Procs pro Minute\nEure Zauber und Fähigkeiten haben eine Chance, einen Schwarm Geisteradler zu beschwören, die auf Gegner in der Nähe herabstürzen und bei Aufprall explodieren. Explosionen heilen Verbündete und fügen Gegnern innerhalb von 5 Metern [[2 * (368% Angriffs-/Zaubermacht)]][[(368% Angriffs-/Zaubermacht)]] Naturschaden zu." }
