entries[1235165] = { ["name"] = "Schwärende Sense", ["text"] = "Sofort\nJeder 20. Einsatz von 'Schwärende Wunden' bewirkt, dass Euer nächster 'Schwärender Stoß' zu 'Schwärende Sense' wird.\n\nSchwärende Sense\nFegt durch alle Gegner innerhalb von 14 Metern vor Euch, fügt ihnen (200% der Angriffskraft) Schattenschaden zu und infiziert sie mit 2 bis 3 Stapeln von 'Schwärende Wunde'." }
