entries[1235368] = { ["name"] = "Arkanes Schlitzen", ["text"] = "100 Meter Reichweite\nWirken in 3 sek.\nSchießt arkane Energie in Richtung des aktuellen Ziels, die Spielercharakteren in einem kegelförmigen Bereich 4848899 Arkanschaden sowie zusätzlich 9 Sek. lang alle 1.5 Sek. 1697115 Arkanschaden zufügen. Dieser Effekt ist stapelbar." }
