entries[1235371] = { ["name"] = "Frostfieber", ["text"] = "Unbegrenzte Reichweite\nSofort\nEine Krankheit, die im Verlauf von 30 Sek. [(214% der Angriffskraft) * [(Angriffskraft * 0.98)][((Angriffskraft + Schildhand-Angriffskraft) * 2 / 3)] -- 2H, DW / Angriffskraft] Frostschaden verursacht und jedes Mal, wenn sie Schaden verursacht, eine Chance hat, dem Todesritter (40 / 10) Runenmacht zu gewähren." }
entries[1235372] = { ["name"] = "Blutseuche", ["text"] = "Unbegrenzte Reichweite\nSofort\nEine schattenhafte Krankheit, die dem Ziel im Verlauf von 30 Sek. 0 Gesundheit entzieht." }
entries[1235382] = { ["name"] = "Bevorstehender Sieg", ["text"] = "Nahkampfreichweite\nSofort\nGreift das Ziel sofort an, verursacht 30846 Schaden und heilt Euch um 30% Eurer maximalen Gesundheit.\n\nNach dem Töten eines Gegners, der Erfahrung oder Ehre gewährt, wird die Abklingzeit von 'Bevorstehender Sieg' abgeschlossen und die Fähigkeit kostet keine Wut." }
entries[1235383] = { ["name"] = "Zerschmettern", ["text"] = "20 Energie Nahkampfreichweite\nSofort\nBenötigt Nahkampfwaffe\nZerschmettert einen Gegner und fügt ihm 42086 körperlichen Schaden zu." }
entries[1235386] = { ["name"] = "Hinrichten", ["text"] = "20 Energie Nahkampfreichweite\nSofort 3.5 sek. Abklingzeit\nBenötigt Nahkampfwaffe\nVersucht, einen Gegner zu erledigen und verursacht dabei 335637 körperlichen Schaden." }
entries[1235387] = { ["name"] = "Naazindhris Mystische Peitsche", ["text"] = "Ca. 2.5 Procs pro Minute\nEure Schaden verursachenden Zauber haben eine hohe Chance, Euer Ziel mit arkaner Macht zu peitschen, was ( 644 * 1 ) Arkanschaden verursacht, der auf Euer Ziel und die Gegner in Eurer Bahn aufgeteilt wird.\n\nDer Schaden wird für jeden weiteren Gegner um 30%, bis zu 150%, und basierend auf Eurer Meisterschaft noch weiter erhöht." }
entries[1235388] = { ["name"] = "Zorn des Wildtiers", ["text"] = "100 Meter Reichweite\nSofort\nAlphatiere werden nun Eurem 'Tötungsbefehl' gehorchen und Schaden mit 30% Effektivität verursachen.\n\n'Zorn des Wildtiers' versetzt Euer Alphatier nun in Zorn und erhöht seinen verursachten Schaden für 15 Sek. um 15%. Alphatiere, die im Zuge von 'Zorn des Wildtiers' beschworen wurden, profitieren für eine verkürzte Dauer von diesem Effekt." }
entries[1235391] = { ["name"] = "Dunkle Transformation", ["text"] = "100 Meter Reichweite\nSofort\n[ Schlickspucker : Eure Monstrosität ] [ Glyphe 'Spuk' : Euer Spuk / Euer Ghul ] fügt 5 Gegnern in der Nähe (44.73% der Angriffskraft) Schattenschaden zu und verwandelt sich für 15 Sek. in ein mächtiges untotes Monster. [ Dunkle Transformation : Gewährt ihnen 100% Energie und die / die] Fähigkeiten [ Schlickspucker : der Monstrosität ] [ Glyphe 'Spuk' : des Spuks / des Ghuls ] werden dadurch mächtiger und erhalten neue Funktionen, solange die Transformation anhält." }
