entries[1235490] = { ["name"] = "Astrophysischer Strahl", ["text"] = "Unbegrenzte Reichweite\nWirken in 3 sek.\nDimensius durchtrennt den Raum mit einem enormen Strahlungsstrom, der allen Spielercharakteren, die ihm zu nahe kommen, alle 1 Sek. 14053831 kosmischen Schaden zufügt.\n\nSpielercharaktere, die versuchen, das Zentrum des Strahls zu durchqueren, werden augenblicklich verdampft." }
