entries[1235879] = { ["name"] = "Erzürnt", ["text"] = "Sofort\nWenn Ihr Schaden erleidet, werdet Ihr erzürnt, wodurch Ihr 202 Schaden absorbiert und 461 Schattenschaden pro Erzürnung verursacht, der auf Gegner in der Nähe aufgeteilt wird. Schaden pro zusätzlichem Gegner um 30% erhöht, bis maximal 150%.\n\nIhr könnt alle 15 Sek. erneut erzürnt gemacht werden, bis zu 15 Stapeln, beruhigt Euch nach Ende des Kampfes aber schnell.\n\nGilt nur für Tankspezialisierungen." }
