entries[1235934] = { ["name"] = "Hammer des Lichts", ["text"] = "100 Meter Reichweite\nSofort\nHämmert mit der Macht des Lichts auf Euren Gegner ein, was diesem (580.645% der Angriffskraft) Heiligschaden und bis zu 4 Gegnern in der Nähe (290% der Angriffskraft) Heiligschaden zufügt.\n\nRuft außerdem Himmelshämmer herab, die 3 Gegner in der Nähe treffen und ihnen jeweils (46.55% der Angriffskraft) Heiligschaden zufügen." }
entries[1235946] = { ["name"] = "Mal des unablässigen Zorns", ["text"] = "Sofort\nWenn Ihr Schaden erleidet, werdet Ihr erzürnt, wodurch Ihr 202 Schaden absorbiert und 461 Schattenschaden pro Erzürnung verursacht, der auf Gegner in der Nähe aufgeteilt wird. Schaden pro zusätzlichem Gegner um 30% erhöht, bis maximal 150%.\n\nIhr könnt alle 15 Sek. erneut erzürnt gemacht werden, bis zu 15 Stapeln, beruhigt Euch nach Ende des Kampfes aber schnell.\n\nGilt nur für Tankspezialisierungen." }
entries[1235959] = { ["name"] = "Mage Spellslinger 11.2 Class Set 2pc", ["text"] = "Arkan\nSchaden von 'Arkanschlag' um 12% erhöht, und 'Arkanschlag' gewährt 1 Stapel von 'Arkane Harmonie'. Direkter 'Splitter'-Schaden gewährt mit einer Chance von 25% einen Stapel 'Arkane Harmonie'.\n\nFeuer, Frost\nSchaden von 'Eislanze' und 'Eiszapfen' um 10% erhöht, und 'Eislanze' hat eine Chance von 50%, 1 Stapel von 'Kaltfront' zu gewähren. Direkter 'Splitter'-Schaden gewährt mit einer Chance von 15% einen Stapel 'Kaltfront'." }
entries[1235962] = { ["name"] = "Mage Sunfury 11.2 Class Set 2pc", ["text"] = "Arkan, Feuer, Frost\nDer Zauberschadensbonus von 'Zauberfeuersphäre' ist um 1.0% erhöht. 'Manakaskade' gewährt nun zusätzlich 0.5% Tempo pro Stapel." }
entries[1235963] = { ["name"] = "Mage Frostfire 11.2 Class Set 2pc", ["text"] = "Feuer\nDer Schaden von 'Kometenhagel' und 'Frostfeuerausstoß' wird um 15% erhöht. Der Schaden von 'Frostfeuerblitz' wird um 8% erhöht. 'Kometenhagel', 'Frostfeuerausstoß' und 'Frostfeuerblitz' verursachen jetzt 'Entzünden' mit 75% Effektivität.\n\nArkan, Frost\nDer Schaden von 'Meteor' und 'Frostfeuerausstoß' wird um 30% erhöht. Der Schaden von 'Frostfeuerblitz' wird um 10% erhöht. 'Meteor', 'Frostfeuerausstoß' und 'Frostfeuerblitz' verursachen jetzt 'Entzünden', wodurch zusätzlich 9 Sek. lang 25 Schaden verursacht wird." }
entries[1235964] = { ["name"] = "Mage Spellslinger 11.2 Class Set 4pc", ["text"] = "Arkan\nSplitterschaden um 8% erhöht. 'Arkane Kugel' gewährt mit einer Chance von 100% bis zu 8-mal einen Stapel 'Arkane Harmonie'. Bei Erreichen von 20 Stapeln 'Arkane Harmonie' erhaltet Ihr 'Intuition' zu 100% Effektivität. lang um 8%.\n\nFeuer\nSplitterschaden um 8% erhöht. 'Arkane Kugel' gewährt mit einer Chance von 100% bis zu 8-mal einen Stapel 'Arkane Harmonie'. Wenn 'Kaltfront' eine 'Gefrorene Kugel' beschwört, erhöht sich Euer Zauberschaden 10 Sek. lang um 8%.\n\nFrost\nWenn 'Gefrorene Kugel' mindestens einem Gegner Schaden zufügt, gewährt sie mit einer Chance von 15% einen Stapel 'Kaltfront'. Wenn 'Kaltfront' eine 'Gefrorene Kugel' beschwört, erhöht sich Euer Zauberschaden 10 Sek. lang um 8%.\n\n(100ms Abklingzeit)" }
entries[1235965] = { ["name"] = "Mage Sunfury 11.2 Class Set 4pc", ["text"] = "Arkan\nAußergewöhnliche Zauber, die von Eurem Phönix gewirkt werden, verlängern die Dauer Eures nächsten Einsatzes von 'Arkane Seele' um 0.5 Sek. Wenn Euer Phönix vergeht, ermächtigt er Euch noch weiter und verleiht Euch 10 Sek. lang eine geringe 'Zeitkrümmung' und 20% erhöhten Zauberschaden.\n\nFeuer, Frost\nAußergewöhnliche Zauber, die von Eurem Phönix gewirkt werden, verlängern die Dauer Eures nächsten Einsatzes von 'Hyperthermie' um 0.3 Sek. Wenn Euer Phönix vergeht, ermächtigt er Euch noch weiter und verleiht Euch 10 Sek. lang eine geringe 'Zeitkrümmung' und 10% erhöhten Zauberschaden." }
entries[1235966] = { ["name"] = "Mage Frostfire 11.2 Class Set 4pc", ["text"] = "Arkan, Frost\nDer Einsatz von 'Gletscherstachel' hat eine Chance von 100%, außerdem einen einen 'Pyroschlag' zu wirken, der (352.5% der Zaubermacht) Feuerschaden verursacht. Außerdem profitiert 'Pyroschlag' jetzt von 'Entzünden'.\n\nFeuer\nDer Einsatz von 'Pyroschlag' hat eine Chance von 20%, außerdem einen 'Gletscherstachel' zu wirken, der (366.24% der Zaubermacht) Frostschaden verursacht. Durch diesen Effekt gewirkte 'Gletscherstachel' verwurzeln nicht. Außerdem profitiert 'Gletscherstachel' jetzt von 'Entzünden'." }
entries[1235967] = { ["name"] = "Leerenköder", ["text"] = "25 Meter Reichweite\nWirken in 1 sek.\nWirft den Leerenköder auf einen Haufen astraler Überreste, um Ramon'ta anzulocken." }
entries[1235973] = { ["name"] = "Rachsüchtige Leerenbarriere", ["text"] = "Sofort\nWenn Ihr Schaden erleidet, werdet Ihr erzürnt, wodurch Ihr 202 Schaden absorbiert und 461 Schattenschaden pro Erzürnung verursacht, der auf Gegner in der Nähe aufgeteilt wird. Schaden pro zusätzlichem Gegner um 30% erhöht, bis maximal 150%.\n\nIhr könnt alle 15 Sek. erneut erzürnt gemacht werden, bis zu 15 Stapeln, beruhigt Euch nach Ende des Kampfes aber schnell.\n\nGilt nur für Tankspezialisierungen." }
entries[1235979] = { ["name"] = "Bildwackeleffekte (alle innerhalb von 40 Metern)" }
entries[1235985] = { ["name"] = "Vertrag: Der Bund von K'aresh", ["text"] = "Sofort\nUnterzeichnet einen Vertrag mit dem Bund von K'aresh, der Euch bis zur wöchentlichen Zurücksetzung jedes Mal 5 Ruf bei dieser Fraktion gewährt, wenn Ihr eine Weltquest in Khaz Algar abschließt.\n\nKriegsmeutenvertrag\nIhr könnt pro Woche nur einen Vertrag unterzeichnen. Dieser Effekt gilt für Eure gesamte Kriegsmeute." }
entries[1235986] = { ["name"] = "Inaktiv" }
entries[1235987] = { ["name"] = "Vertrag: Der Bund von K'aresh", ["text"] = "Sofort\nUnterzeichnet einen Vertrag mit dem Bund von K'aresh, der Euch bis zur wöchentlichen Zurücksetzung jedes Mal 10 Ruf bei dieser Fraktion gewährt, wenn Ihr eine Weltquest in Khaz Algar abschließt.\n\nKriegsmeutenvertrag\nIhr könnt pro Woche nur einen Vertrag unterzeichnen. Dieser Effekt gilt für Eure gesamte Kriegsmeute." }
