entries[1236108] = { ["name"] = "Geladene Blitze", ["text"] = "Eure Zauber und Fähigkeiten haben eine Chance, Euch in einen Blitzableiter zu verwandeln. Damit trefft Ihr 15 Sek. lang alle 3 Sek. ein zufälliges gegnerisches Ziel innerhalb von 40 Metern und fügt ihm ( 1 * 167 ) Naturschaden zu." }
