entries[1236123] = { ["name"] = "Kritische Kette", ["text"] = "Eure Zauber und Fähigkeiten haben eine Chance, 'Kritische Überladung' auszulösen, die Euren kritischen Trefferwert 20 Sek. lang alle 2 Sek. um 31 erhöht." }
entries[1236124] = { ["name"] = "Funkenexplosion", ["text"] = "Eure Zauber und Fähigkeiten haben eine Chance, eine Funkenexplosion auszulösen, die Euer Tempo 20 Sek. lang um 139 erhöht." }
entries[1236126] = { ["name"] = "Bindender Wurfspeer", ["text"] = "100 Meter Reichweite\nSofort\nTaah'bat schleudert arkane Speere auf anvisierte Spielercharaktere, fügt Spielercharakteren innerhalb von 8 Metern um die Ziele 2424449 Arkanschaden zu und fesselt alle getroffenen Spielercharaktere.\n\nJede Fessel verursacht alle 1 Sek. 606112 Arkanschaden und verringert die Bewegungsgeschwindigkeit um 50%. Die Wirkung verstärkt sich alle 5 Sek., bis der Speer zerstört wird. Dieser Effekt ist stapelbar." }
entries[1236127] = { ["name"] = "Seelenausstoß", ["text"] = "30 Meter Reichweite\nSofort\nDie entfesselte Seele entschwindet beim Sterben rasch in die Leere und fügt Spielercharakteren innerhalb von 30 Metern 2 Arkanschaden zu." }
entries[1236128] = { ["name"] = "Statische Aufladung", ["text"] = "Eure Zauber und Fähigkeiten haben eine Chance, Euch 'Statische Aufladung' zu gewähren, die Eure Vielseitigkeit 30 Sek. lang um ( 14 * 20) erhöht. Jeder Eurer nächsten Einsätze von Zaubern und Fähigkeiten verringert den Vielseitigkeitsbonus um 5%." }
entries[1236129] = { ["name"] = "Elektrische Ladung", ["text"] = "Ihr erlangt zu Kampfbeginn 'Elektrische Ladung', die Eure Meisterschaft alle 2 Sek. um 8 erhöht, bis maximal (12 * 8 ). Nach 24 Sek. fällt der Zyklus wieder ab und wiederholt sich." }
entries[1236130] = { ["name"] = "Bindender Wurfspeer", ["text"] = "100 Meter Reichweite\nWirken in 3 sek.\nTaah'bat schleudert arkane Speere auf anvisierte Spielercharaktere, fügt Spielercharakteren innerhalb von 8 Metern um die Ziele 2424449 Arkanschaden zu und fesselt alle getroffenen Spielercharaktere.\n\nJede Fessel verursacht alle 1 Sek. 606112 Arkanschaden und verringert die Bewegungsgeschwindigkeit um 50%. Die Wirkung verstärkt sich alle 5 Sek., bis der Speer zerstört wird. Dieser Effekt ist stapelbar." }
entries[1236132] = { ["name"] = "Aufgeladene Berührung", ["text"] = "Eure Heilzauber haben eine Chance, auf das Ziel mit der geringsten Gesundheit innerhalb von 40 Metern überzuspringen und es um 1766 Gesundheit zu heilen." }
entries[1236133] = { ["name"] = "Sanktuariosprachen", ["text"] = "30 Meter Reichweite\nSofort\nZwingt Gegner in der Nähe, in Sanktuariosprache zu sprechen, was ihr Zaubertempo bis Abbruch lang um 10% verringert." }
entries[1236134] = { ["name"] = "Energieschild", ["text"] = "Wenn Ihr Schaden erleidet, habt Ihr eine Chance, einen titanischen Energieschild zu erlangen, der 10 Sek. lang bis zu 3662 Schaden aufhebt. Wenn der Schild abläuft, verursacht er 30% der verbleibenden Absorption als Arkanschaden, aufgeteilt auf Gegner innerhalb von 8 Metern." }
entries[1236135] = { ["name"] = "Aufgeladener Kristall", ["text"] = "Eure Zauber und Angriffe haben eine Chance, 'Geladener Blitz' auf Euer Ziel niedergehen zu lassen, was 965 Naturschaden verursacht, aufgeteilt auf Ziele innerhalb von 8 Metern." }
