entries[1236160] = { ["name"] = "Entzünden", ["text"] = "Unbegrenzte Reichweite\nSofort\nEuer Ziel erleidet im Verlauf von 9 Sek. zusätzlichen Feuerschaden in Höhe von 4.0% des gesamten direkten Schadens, den Ihr mit Euren Zaubern 'Feuerball', 'Feuerschlag', 'Versengen', 'Pyroschlag' [ Meteor : 'Meteor' ] [ Phönixflammen : 'Phönixflammen' ] [ Funkensturm : 'Funkensturm' ] und 'Flammenstoß' verursacht. Wenn dieser Effekt erneut angewendet wird, wird der verbleibende Schaden dem neuen Effekt von 'Entzünden' hinzugefügt.\n\n'Feuerschlag' bewirkt, dass Euer Effekt 'Entzünden' sich auf 3 Gegner in der Nähe ausbreitet." }
entries[1236161] = { ["name"] = "Aufgeladene Berührung", ["text"] = "Funken fliegen, wenn Brann geheilt wird, und fügen einem gegnerischen Ziel innerhalb von 40 Metern Schaden in Höhe der verursachten Heilung zu." }
entries[1236169] = { ["name"] = "Aufgeladener Kristall", ["text"] = "Wenn Ihr einen titanischen Sturmkristall zerstört, lasst Ihr sofort einen aufgeladenen Blitz auf einen Gegner innerhalb von 40 Metern niedergehen." }
