entries[1236193] = { ["name"] = "Kraft entziehen", ["text"] = "20 Meter Reichweite\nKanalisiert (Wirken in 5 sek.)\nDer Zaubernde entzieht einem Kristall in der Nähe Energie und schleudert gelegentlich ' Entzugsentladung ' auf Spielercharaktere innerhalb von 60 Metern.\n\nNach der Kanalisierung erhöht sich der verursachte Schaden des Zaubernden um 50%." }
