entries[1236207] = { ["name"] = "Astrale Woge", ["text"] = "Unbegrenzte Reichweite\nSofort\nBei Kontakt mit 'Arkane Manifestation' strömt Energie in den arkanen Sammler und fügt allen Spielercharakteren 22623435 Arkanschaden sowie zusätzlich 16 Sek. lang alle 2 Sek. 8432299 Arkanschaden zu." }
entries[1236209] = { ["name"] = "Gletscherstachel", ["text"] = "1% von Grundmana 40 Meter Reichweite\nWirken in 2.75 sek.\nBeschwört einen gewaltigen Eisstachel herbei, der Eure gesamten aktiven Eiszapfen in sich vereint. Er spießt Euer Ziel auf und verursacht (654% der Zaubermacht) Schaden sowie zusätzlich den gesamten in Euren Eiszapfen gespeicherten Schaden. Friert Euer Ziel außerdem 4 Sek. lang an Ort und Stelle fest. Dem Ziel zugefügter Schaden kann den Effekt unterbrechen.\n\nZum Wirken werden 5 Eiszapfen benötigt.\n\nPassiv: 'Eislanze' lässt keine Eiszapfen mehr auf das Ziel niedergehen." }
entries[1236211] = { ["name"] = "Gletscherstachel", ["text"] = "100 Meter Reichweite\nSofort\nBeschwört einen gewaltigen Eisstachel herbei, der Eure gesamten aktiven Eiszapfen in sich vereint. Er spießt Euer Ziel auf und verursacht (654% der Zaubermacht) Schaden sowie zusätzlich den gesamten in Euren Eiszapfen gespeicherten Schaden. Friert Euer Ziel außerdem 4 Sek. lang an Ort und Stelle fest. Dem Ziel zugefügter Schaden kann den Effekt unterbrechen.\n\nZum Wirken werden 5 Eiszapfen benötigt.\n\nPassiv: 'Eislanze' lässt keine Eiszapfen mehr auf das Ziel niedergehen." }
entries[1236212] = { ["name"] = "Pyroschlag", ["text"] = "1.5% von Grundmana 40 Meter Reichweite\nWirken in 4 sek.\nSchleudert einen immensen feurigen Felsen, der (352.5% der Zaubermacht) Feuerschaden (18.6% der Zaubermacht) zusätzlichen Feuerschaden verursacht." }
