entries[1236253] = { ["name"] = "Death Knight Deathbringer 11.2 Class Set 2pc", ["text"] = "Frost, Unheilig\nDer Einsatz von 'Mal des Schnitters' erzeugt 1 Stapel von 'Ausmerzen' mit 150% der Effektivität der ersten und 125% der Effektivität der zweiten Sense.\n\nBlut\nDer Einsatz von 'Mal des Schnitters' erzeugt 2 Stapel von 'Ausmerzen' mit 150% der Effektivität der ersten und 125% der Effektivität der zweiten Sense." }
entries[1236254] = { ["name"] = "Death Knight Deathbringer 11.2 Class Set 4pc", ["text"] = "Blut, Frost, Unheilig\n'Exterminieren' verursacht 20% mehr Schaden und 'Mal des Schnitters' ist bis zu 15-mal zusätzlich stapelbar. Wenn es explodiert, erhöht 'Mal des Schnitters' Eure kritische Trefferchance 8 Sek. lang um 10%.\n(1s Abklingzeit)" }
entries[1236256] = { ["name"] = "Vorpalspalten", ["text"] = "10 Meter Reichweite\nWirken in 2.5 sek.\nDer Zaubernde spaltet den Bereich vor ihm, verursacht Schattenschaden und belegt getroffene Spielercharaktere mit einem Heilungsabsorptionsschild." }
entries[1236259] = { ["name"] = "Death Knight San'layn 11.2 Class Set 2pc", ["text"] = "Unheilig\nDer Einsatz von 'Kummer bereiten' verlängert die Dauer Eurer Krankheit auf Eurem Primärziel um zusätzliche 3.0 Sek. und 'Essenz der Blutkönigin' erhöht Eure Meisterschaft zusätzlich um 0.5% pro Stapel.\n\nBlut, Frost\nDer Einsatz von 'Kummer bereiten' verlängert die Dauer Eurer Krankheit auf Eurem Primärziel um zusätzliche 4.0 Sek. und 'Essenz der Blutkönigin' erhöht Eure Meisterschaft zusätzlich um 0.5% pro Stapel." }
entries[1236260] = { ["name"] = "Death Knight San'layn 11.2 Class Set 4pc", ["text"] = "Unheilig\nEure Fähigkeit 'Kummer bereiten' verursacht 30% mehr Schaden und der Einsatz von 'Vampirstoß' erhöht den Schaden Eurer nächsten Einsätze von Ghule 8 Sek. lang um 20%. Mehrere Anwendungen können sich überlappen.\n\nBlut, Frost\nEure Fähigkeit 'Kummer bereiten' verursacht 50% mehr Schaden und der Einsatz von 'Vampirstoß' erhöht den Schaden Eurer nächsten Einsätze von Tanzende Runenwaffen 8 Sek. lang um 20%. Mehrere Anwendungen können sich überlappen." }
entries[1236262] = { ["name"] = "Shaohaos Weisenschlange", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Die Lektionen, die Shaohao während seiner Lebzeiten und im Tod gelernt und die Leidenschaft, die er für seine Heimat verspürt hat, haben sich zu dieser ätherischen Schlange verschmolzen: eine Reflektion der Weisheit des Kaisers.\"\nPromotion:\nMists of Pandaria Classic" }
