entries[1236275] = { ["name"] = "Statische Aufladung", ["text"] = "Sofort\nCa. 1.5 Procs pro Minute\nEure Zauber und Fähigkeiten haben eine Chance, Euch 'Statische Aufladung' zu gewähren, die Eure Vielseitigkeit 30 Sek. lang um ( 14 * 20) erhöht. Jeder Eurer nächsten Einsätze von Zaubern und Fähigkeiten verringert den Vielseitigkeitsbonus um 5%.\n(29s Abklingzeit)" }
entries[1236276] = { ["name"] = "Elektrische Ladung", ["text"] = "Sofort\nIhr erlangt zu Kampfbeginn 'Elektrische Ladung', die Eure Meisterschaft alle 2 Sek. um 8 erhöht, bis maximal (12 * 8 ). Nach 24 Sek. fällt der Zyklus wieder ab und wiederholt sich." }
entries[1236277] = { ["name"] = "Aufgeladene Berührung", ["text"] = "Sofort\nCa. 2 Procs pro Minute\nEure Heilzauber haben eine Chance, auf das Ziel mit der geringsten Gesundheit innerhalb von 40 Metern überzuspringen und es um 1766 Gesundheit zu heilen." }
entries[1236278] = { ["name"] = "Energieschild", ["text"] = "Sofort\nCa. 1.5 Procs pro Minute\nWenn Ihr Schaden erleidet, habt Ihr eine Chance, einen titanischen Energieschild zu erlangen, der 10 Sek. lang bis zu 3662 Schaden aufhebt. Wenn der Schild abläuft, verursacht er 30% der verbleibenden Absorption als Arkanschaden, aufgeteilt auf Gegner innerhalb von 8 Metern." }
entries[1236279] = { ["name"] = "Aufgeladener Kristall", ["text"] = "Sofort\nCa. 1.5 Procs pro Minute\nEure Zauber und Angriffe haben eine Chance, 'Geladener Blitz' auf Euer Ziel niedergehen zu lassen, was 965 Naturschaden verursacht, aufgeteilt auf Ziele innerhalb von 8 Metern." }
