entries[1236298] = { ["name"] = "Gebräu abliefern", ["text"] = "20 Meter Reichweite\nWirken in 0.5 sek. 1 sek. Abklingzeit\nReagenzien:\nGebräufass\nSchüttet das Gebräu in das Servierfass." }
