entries[1236329] = { ["name"] = "Nächstes Abenteuer anzeigen", ["text"] = "Sofort\nZeigt Optionen an, wohin Ihr als Nächstes gehen könnt.\n\nIhr könnt die Aufholerfahrung jederzeit von Eurem Abenteuerführer aus wiederholen." }
entries[1236330] = { ["name"] = "Druid Druid of the Claw 11.2 Class Set 4pc", ["text"] = "Wildheit\nBeim Einsatz von 'Verheeren' besteht eine Chance von 40%, dass Ihr Euer Ziel 4 Sek. später mit 100% Effektivität erneut verheert.\n\nGleichgewicht, Wächter, Wiederherstellung\nBeim Einsatz von 'Verheeren' besteht eine Chance von 40%, dass Ihr Euer Ziel 4 Sek. später mit 60% Effektivität erneut verheert." }
entries[1236331] = { ["name"] = "Druid Druid of the Claw 11.2 Class Set 2pc", ["text"] = "Der Einsatz von 'Verheeren' erhöht 5 Sek. lang Euer Tempo um 10%, Eure kritische Trefferchance um 10% und Euren verursachten Blutungsschaden um 30%.\n(100ms Abklingzeit)" }
entries[1236332] = { ["name"] = "Druid Elune's Chosen 11.2 Class Set 2pc", ["text"] = "Wildheit, Wächter, Wiederherstellung\nDer Schaden von 'Hauen' ist um 20% erhöht. Beim Einsatz von 'Hauen' besteht eine Chance von 40%, dass ein 'Sternensog' mit 160% Effektivität gegen einen Gegner ausgelöst wird.\n\nGleichgewicht\nDer Schaden von 'Sternenfeuer' ist um 15% erhöht. Wenn Ihr Astrale Macht durch 'Sternenfeuer' erhaltet, besteht eine Chance von 40%, dass ein 'Sternensog' mit 45% Effektivität gegen einen Gegner ausgelöst wird.\n\n(100ms Abklingzeit)" }
entries[1236333] = { ["name"] = "Druid Elune's Chosen 11.2 Class Set 4pc", ["text"] = "Wildheit, Wächter, Wiederherstellung\nEin 'Sternensog', der durch 'Hauen' ausgelöst wurde, spaltet sich beim Einschlag mit 20% Effektivität auf bis zu 3 zusätzliche Ziele auf und erzeugt einen Stapel von 'Mondlicht sammeln'. Der Einsatz von 'Mondstrahl' verbraucht 'Mondlicht sammeln', um Euren Schaden 12 Sek. lang um 4% pro Stapel zu erhöhen.\n\nGleichgewicht\nEin 'Sternensog', der durch 'Sternenfeuer' ausgelöst wurde, spaltet sich beim Einschlag mit 40% Effektivität auf bis zu 3 zusätzliche Ziele auf und erzeugt einen Stapel von 'Mondlicht sammeln'. Der Einsatz von 'Zorn der Elune' oder 'Vollmond' verbraucht 'Mondlicht sammeln', um Euren Schaden 12 Sek. lang um 4% pro Stapel zu erhöhen." }
entries[1236334] = { ["name"] = "Druid Keeper of the Grove 11.2 Class Set 2pc", ["text"] = "Gleichgewicht, Wildheit, Wächter\nDer Einsatz von 'Himmlische Ausrichtung' erbittet für 10 Sek. die Unterstützung einer Dryade, die 'Sternensog' mit 360% Effektivität' und 'Sternenregen' mit 800% Effektivität wirkt.\n\nWiederherstellung\nDer Einsatz von 'Inkarnation: Baum des Lebens' oder 'Konvokation der Geister' erbittet für 5 Sek. die Unterstützung einer Dryade, die 'Gelassenheit' mit 50% Effektivität wirkt und Euren Verbündeten mit der niedrigsten Gesundheit sofort mit 200% Effektivität 'Nachwachsen' lässt." }
entries[1236336] = { ["name"] = "Druid Keeper of the Grove 11.2 Class Set 4pc", ["text"] = "Wiederherstellung\nWenn Eure Dryade vergeht, verursachen Eure nächsten 2 Einsätze von 'Rasche Heilung' zusätzliche Heilung in Höhe von 5% der verursachten Heilung, während sie aktiv war, und 25% der Heilung greift auf Verbündete in der Nähe über. Wird nach dem 5. Ziel reduziert.\n\nGleichgewicht, Wildheit, Wächter\nWenn Eure Dryade vergeht, verursachen Eure nächsten 2 Einsätze von 'Sternensog' zusätzlichen Schaden in Höhe von 3% des verursachten Schadens, während sie aktiv war, und 10% des Schadens greift auf Gegner in der Nähe über. Wird nach dem 5. Ziel reduziert." }
entries[1236337] = { ["name"] = "Druid Wildstalker 11.2 Class Set 2pc", ["text"] = "Wildheit\nDie Wachstumsrate von 'Blutsucherranken' ist um 40% erhöht.Der Einsatz von $?c2['Tigerfuror' lässt 'Blutsucherranken' auf bis zu 3 verfügbare Gegner in der Nähe übergreifen.\n\nGleichgewicht, Wächter, Wiederherstellung\nDie Wachstumsrate von 'Symbiotische Blüte' ist um 45% erhöht.'Nachwachsen' mit 'Freizaubern' lässt 'Symbiotische Blüte' auf bis zu 2 verfügbare Verbündete in der Nähe übergreifen.", ["unresolvedValues"] = true }
entries[1236338] = { ["name"] = "Druid Wildstalker 11.2 Class Set 4pc", ["text"] = "Wildheit\nBeim Einsatz von 'Blutsucherranken' besteht alle 2 Sek. eine Chance von 20%, dass 'Berstender Wuchs' mit 100% Effektivität ausgelöst wird. Jeder Stapel von 'Blutsucherranken' auf einem Gegner erhöht den Schaden durch 'Berstender Wuchs' um 40%.\n\nGleichgewicht, Wächter, Wiederherstellung\nBeim Einsatz von 'Symbiotische Blüte' besteht alle 2 Sek. eine Chance von 35%, dass 'Berstender Wuchs' mit 100% Effektivität ausgelöst wird. Jeder Stapel von 'Symbiotische Blüte' auf einem Verbündeten erhöht die Heilung durch 'Berstender Wuchs' um 30%." }
entries[1236342] = { ["name"] = "Angriffsvorbereitung", ["text"] = "Sofort\nWildheit\nBeim Einsatz von 'Verheeren' besteht eine Chance von 40%, dass Ihr Euer Ziel 4 Sek. später mit 100% Effektivität erneut verheert.\n\nGleichgewicht, Wächter, Wiederherstellung\nBeim Einsatz von 'Verheeren' besteht eine Chance von 40%, dass Ihr Euer Ziel 4 Sek. später mit 60% Effektivität erneut verheert." }
entries[1236343] = { ["name"] = "Abgründige Detonation" }
entries[1236348] = { ["name"] = "Aufgeladenes Schlitzen", ["text"] = "100 Meter Reichweite\nWirken in 4 sek. 3 sek. Abklingzeit\nZo'phex lädt sein Schwert auf und führt einen massiven Hieb, der allen Gegnern vor ihm 15758921 körperlichen Schaden zufügt." }
entries[1236350] = { ["name"] = "Void Power Shard Released Visuals - COSMETIC" }
entries[1236354] = { ["name"] = "Seelensauger", ["text"] = "40 Meter Reichweite\nWirken in 2 sek. 5 sek. Abklingzeit\nDer Zaubernde verlangsamt sein Ziel und entzieht ihm im Verlauf von 8 Sek. insgesamt 622547 Gesundheit. Der Zaubernde wird um das Doppelte des entzogenen Betrags geheilt." }
entries[1236355] = { ["name"] = "Death Knight Rider of the Apocalypse 11.2 Class Set 2pc", ["text"] = "Blut, Unheilig\nDer Einsatz von 'Apokalypse' beschwört jetzt Weißsträhne für 10 Sek. 'Weißsträhnes Untod' verursacht 20% mehr Schaden und infiziert bei Ausbreitung 1 zusätzliche Ziele, und ihr 'Todesmantel' verursacht 35% mehr Schaden.\n\nFrost\nDer Einsatz von Säule des Frosts beschwört jetzt Trollbann für 10 Sek. 'Trollbanns eisiger Zorn' verursacht 20% mehr Schaden und sein 'Auslöschen' verursacht 15% mehr Schaden." }
entries[1236356] = { ["name"] = "Death Knight Rider of the Apocalypse 11.2 Class Set 4pc", ["text"] = "Frost\nDer Einsatz von 'Auslöschen' oder 'Frostsichel' befiehlt Trollbann, ebenfalls 'Auslöschen' oder 'Frostsichel' mit 100% Effektivität einzusetzen. Euer 'Auslöschen' verursacht 20% mehr Schaden gegen Ziele, die von 'Trollbanns eisiger Zorn' betroffen sind.\n\nBlut, Unheilig\nDer Einsatz von 'Todesmantel' oder 'Epidemie' befiehlt Weißsträhne, ebenfalls 'Todesmantel' oder 'Epidemie' mit 125% Effektivität einzusetzen. Euer 'Todesmantel' verursacht 40% mehr Schaden gegen Ziele, die von 'Weißsträhnes Untod' betroffen sind.\n\n(500ms Abklingzeit)" }
entries[1236358] = { ["name"] = "Demon Hunter Aldrachi Reaver 11.2 Class Set 2pc", ["text"] = "Der Schaden von 'Gleve des Reißers' ist um 50% erhöht und anderer rein körperlicher Schaden ist um 25% erhöht." }
entries[1236360] = { ["name"] = "Demon Hunter Aldrachi Reaver 11.2 Class Set 4pc", ["text"] = "Verwüstung\nDer Einsatz von 'Wut der Aldrachi' ermächtigt den Einsatz von 'Klingentanz' im Anschluss an 'Chaosstoß' weiter, was die Anzahl der Schnitte auf 12 erhöht.\n\n'Mal des Reißers' ist jetzt bis zu 2-mal stapelbar und ermächtigt den Einsatz von 'Chaosstoß' im Anschluss an 'Klingentanz' weiter, was einen zusätzlichen Stapel für 100% der normalen Dauer erzeugt.\n\nRachsucht\nDer Einsatz von 'Wut der Aldrachi' ermächtigt den Einsatz von 'Seelenspalter' im Anschluss an 'Abscheren' weiter, was die Anzahl der Schnitte auf 12 erhöht.\n\n'Mal des Reißers' ist jetzt bis zu 2-mal stapelbar und ermächtigt den Einsatz von 'Abscheren' im Anschluss an 'Seelenspalter' weiter, was einen zusätzlichen Stapel für 100% der normalen Dauer erzeugt." }
entries[1236361] = { ["name"] = "Demon Hunter Fel-Scarred 11.2 Class Set 2pc", ["text"] = "Verwüstung\nDer Einsatz von 'Feuerbrandaura' verursacht 30% mehr Schaden und erhöht den Schaden von 'Chaosstoß' während der aktiven Dauer um 20%.\n\nRachsucht\nDer Einsatz von 'Feuerbrandaura' verursacht 30% mehr Schaden und erhöht den Schaden von 'Seelenspalter' während der aktiven Dauer um 20%." }
entries[1236362] = { ["name"] = "Demon Hunter Fel-Scarred 11.2 Class Set 4pc", ["text"] = "Verwüstung\nWenn Ihr Dämonenform annehmt, wird sofort eine Dämonenwoge ausgelöst und ein Dämonenseelenfragment zerbrochen, was 10 Sek. lang 20% Schaden verursacht.\n\nRachsucht\nWenn Ihr Dämonenform annehmt, wird sofort eine Dämonenwoge ausgelöst und ein Dämonenseelenfragment zerbrochen, was 15 Sek. lang 20% Schaden verursacht.\n\n(100ms Abklingzeit)" }
entries[1236364] = { ["name"] = "Evoker Flameshaper 11.2 Class Set 2pc", ["text"] = "Der Einsatz von 'Umhüllen' schürt Eure 'Innere Flamme', was Euren regelmäßigen Schaden und Heilung um 25% erhöht und Eure Chance, eine 'Essenzexplosion' zu erhalten, 12 Sek. lang um 50% erhöht. Bis zu 2-mal stapelbar. Mehrere Anwendungen können sich überlappen." }
entries[1236365] = { ["name"] = "Evoker Flameshaper 11.2 Class Set 4pc", ["text"] = "Verheerung\nWenn Ihr 'Essenzexplosion' verbraucht, während 'Innere Flamme' aktiv ist, wird eine 'Essenzbombe' auf Euer Ziel abgefeuert, die Gegnern in der Nähe (371% der Zaubermacht) Schaden zufügt. Wird nach dem 5. Ziel reduziert.\n\nBewahrung, Verstärkung\nWenn Ihr 'Essenzexplosion' verbraucht, während 'Innere Flamme' aktiv ist, wird eine 'Essenzbombe' auf Euer Ziel abgefeuert, die Verbündete in der Nähe um (250% der Zaubermacht) heilt. Wird nach dem 5. Ziel reduziert." }
entries[1236366] = { ["name"] = "Evoker Scalecommander 11.2 Class Set 2pc", ["text"] = "Verheerung, Bewahrung\nWährend Ihr fliegt, solange 'Tiefer Atem' aktiv ist, und 10 Sek. im Anschluss, befehligt Ihr ein Geschwader aus 2 Dracthyr, die Eure Ziele mit 'Desintegrieren' und 'Scheiterhaufen' angreifen.\n\nVerstärkung\nWährend Ihr fliegt, solange 'Tiefer Atem' aktiv ist, und 20 Sek. im Anschluss, befehligt Ihr ein Geschwader aus 2 Dracthyr, die Eure Ziele mit 'Desintegrieren' und 'Scheiterhaufen' angreifen." }
entries[1236367] = { ["name"] = "Evoker Scalecommander 11.2 Class Set 4pc", ["text"] = "Verheerung\nWährend Euer Geschwader aktiv ist, treffen Eure Einsätze von 'Massendesintegration' bis zu 2 zusätzliche Ziele. Außerdem unterstützt Euch Euer Geschwader für 5 weitere Sek.\n\nVerstärkung\nWährend Euer Geschwader aktiv ist, treffen Eure Einsätze von 'Masseneruption' bis zu 2 zusätzliche Ziele. Außerdem unterstützt Euch Euer Geschwader für 10 weitere Sek.\n\nBewahrung\nWährend Euer Geschwader aktiv ist, treffen Eure Einsätze von 'Masseneruption' bis zu 2 zusätzliche Ziele. Außerdem unterstützt Euch Euer Geschwader für 5 weitere Sek." }
entries[1236368] = { ["name"] = "Evoker Chronowarden 11.2 Class Set 2pc", ["text"] = "Die Abklingzeit von 'Zeitdruck' ist um 60 Sek. verringert." }
entries[1236369] = { ["name"] = "Evoker Chronowarden 11.2 Class Set 4pc", ["text"] = "Der Einsatz von 'Temporalexplosion' lässt 'Chronoflammen' 2 zusätzliche Ziele treffen und 15% Schaden oder Heilung wiederholen, bis zu einem Maximum von [(Zaubermacht * 4.5) * (1 + Vielseitigkeit)]. Erhöht zudem den Schaden und die Heilung von Essenzfähigkeiten um 30%." }
entries[1236370] = { ["name"] = "Hunter Dark Ranger 11.2 Class Set 2pc", ["text"] = "Tierherrschaft\nDer Schaden von 'Schwarzer Pfeil' ist um 10% erhöht und der Schaden von 'Düsterpulver' ist um 20% erhöht. Die Abklingzeit von 'Ruf der Wildnis' ist um 60 Sek. verringert.\n\nTreffsicherheit, Überleben\nDer Schaden von 'Schwarzer Pfeil' ist um 10% erhöht und der Schaden von 'Düsterpulver' ist um 20% erhöht. Die Abklingzeit von 'Volltreffer' ist um 30 Sek. verringert." }
entries[1236371] = { ["name"] = "Hunter Dark Ranger 11.2 Class Set 4pc", ["text"] = "Tierherrschaft, Treffsicherheit, Überleben\nDer Schaden der schwarzen Pfeile durch 'Vernichtendes Feuer' ist um 50% erhöht. Wenn 'Todesstoß' verbraucht wird, besteht eine Chance von 50%, dass während Eures nächsten Einsatzes von 'Vernichtendes Feuer' alle Sperrfeuer 1 zusätzliche schwarze Pfeile verschießen." }
entries[1236372] = { ["name"] = "Hunter Pack Leader 11.2 Class Set 2pc", ["text"] = "Treffsicherheit, Überleben\nEure Begleiter verursachen 15% mehr Schaden und Wildtiere 15% mehr Schaden. Die Beschwörung eines Wildtieres verleiht Euch je nach Tierart 8 Sek. lang 6% Tempo, Meisterschaft oder kritische Trefferchance.\n\nTierherrschaft\nEure Begleiter verursachen 5% mehr Schaden und Wildtiere 15% mehr Schaden. Die Beschwörung eines Wildtieres verleiht Euch je nach Tierart 8 Sek. lang 6% Tempo, Meisterschaft oder kritische Trefferchance." }
entries[1236373] = { ["name"] = "Hunter Pack Leader 11.2 Class Set 4pc", ["text"] = "Die Beschwörung eines Wildtiers unter dem Effekt von 'Mit gutem Beispiel voran' versetzt die umliegende Tierwelt in eine Stampede, die auf Euer Ziel zustürmt und über 7 Sek. bis zu 8 Gegnern [(300% der Angriffskraft) * 9] körperlichen Schaden zufügt." }
entries[1236374] = { ["name"] = "Hunter Sentinel 11.2 Class Set 2pc", ["text"] = "Tierherrschaft, Überleben\nErhöht den Schaden von 'Lauffeuerbombe' um 10%. Wenn 'Lunarsturm' abklingt, erhaltet Ihr eine 'Gabe von Elune', wodurch Ihr mit 'Lauffeuerbombe'[Quellwert] 2-mal um 150 erhöhten anfänglichen Schaden als Arkanschaden verursacht.\n\nTreffsicherheit\nErhöht den Schaden von 'Schnellfeuer' um 25%. Wenn 'Lunarsturm' abklingt, erhaltet Ihr eine 'Gabe von Elune', wodurch Ihr mit 'Gezielter Schuss'[Quellwert] 2-mal um 10 erhöhten Schaden als Arkanschaden verursacht.", ["unresolvedValues"] = true }
entries[1236375] = { ["name"] = "Hunter Sentinel 11.2 Class Set 4pc", ["text"] = "Treffsicherheit\nDer Schaden von 'Wachsamer Schütze' ist um 18% erhöht. Die 'Gabe von Elune' ist jetzt für die Dauer von 'Lunarsturm' bei 100% der Effektivität aktiv.\n\nTierherrschaft, Überleben\nDer Schaden von 'Wachsamer Schütze' ist um 20% erhöht. Die 'Gabe von Elune' ist jetzt für die Dauer von 'Lunarsturm' bei 100% der Effektivität aktiv." }
entries[1236376] = { ["name"] = "Seelengeflecht" }
entries[1236377] = { ["name"] = "Monk Master of Harmony 11.2 Class Set 2pc", ["text"] = "Braumeister\nWenn Ihr Lebenskraft erhaltet, besteht eine erhöhte Chance, dass Euer nächster Einsatz von 'Tigerklaue' eine 'Harmonische Welle' auslöst, die auf Euer Ziel und andere Gegner in der Nähe aufgeteilte [180 * (400% der Zaubermacht) / 100] Naturschaden verursacht und bis zu 5 verletzte Verbündete um [20 * (500% der Zaubermacht) / 100] heilt.\n\nWindläufer, Nebelwirker\nWenn Ihr Lebenskraft erhaltet, besteht eine erhöhte Chance, dass Euer nächster Einsatz von 'Tigerklaue' eine 'Harmonische Welle' auslöst, die auf Euer Ziel und andere Gegner in der Nähe aufgeteilte [20 * (400% der Zaubermacht) / 100] Naturschaden verursacht und bis zu 5 verletzte Verbündete um [90 * (500% der Zaubermacht) / 100] heilt." }
entries[1236378] = { ["name"] = "Monk Master of Harmony 11.2 Class Set 4pc", ["text"] = "Windläufer, Nebelwirker\nDer Einsatz von 'Donnerfokustee' garantiert, dass Euer Einsatz von 'Tigerklaue' 2-mal eine 'Harmonische Welle' auslöst.\n\nBraumeister\nDer Einsatz von garantiert, dass Euer Einsatz von 'Tigerklaue' 2-mal eine 'Harmonische Welle' auslöst." }
entries[1236379] = { ["name"] = "Monk Shado-Pan 11.2 Class Set 2pc", ["text"] = "Braumeister\nEuer 'Prügelhagel' verursacht 10% mehr Schaden und die Aktivierung von 'Waffen der Ordnung' generiert sofort 10 Stapel von 'Prügelhagel', die mit 70% Effektivität bei Eurem nächsten Angriff ausgelöst werden.\n\nWindläufer, Nebelwirker\nEuer 'Prügelhagel' verursacht 20% mehr Schaden und die Aktivierung von 'Sturm, Erde und Feuer' generiert sofort 10 Stapel von 'Prügelhagel', die mit 70% Effektivität bei Eurem nächsten Angriff ausgelöst werden." }
entries[1236380] = { ["name"] = "Monk Shado-Pan 11.2 Class Set 4pc", ["text"] = "Windläufer\nDie Ladungserzeugung für 'Schlaghagel' ist um 50% erhöht und, während 'Sturm, Erde und Feuer aktiv ist, wird pro 150 ausgegebener Energie ein 'Prügelhagel' ausgelöst.\n\nBraumeister, Nebelwirker\nDie Ladungserzeugung für 'Schlaghagel' ist um 50% erhöht und, während 'Waffen der Ordnung' aktiv ist, wird pro 150 ausgegebener Energie ein 'Prügelhagel' ausgelöst." }
entries[1236381] = { ["name"] = "Monk Conduit of the Celestials 11.2 Class Set 2pc", ["text"] = "Windläufer\nDer Einsatz von 'Herz der Jadeschlange' wird zusätzlich 4 Sek. lang mit 100% Effektivität ausgelöst, nachdem Ihr 'Schneidende Winde' eingesetzt habt.\n\nBraumeister, Nebelwirker\nDer Einsatz von 'Herz der Jadeschlange' wird zusätzlich 8 Sek. lang mit 100% Effektivität ausgelöst, nachdem Ihr 'Donnerfokustee' eingesetzt habt.\n\n(1s Abklingzeit)" }
entries[1236382] = { ["name"] = "Monk Conduit of the Celestials 11.2 Class Set 4pc", ["text"] = "Der Einsatz von 'Herz der Jadeschlange' erhöht Euer Tempo um 10%, während es aktiv ist, und noch 4 Sek. im Anschluss." }
entries[1236383] = { ["name"] = "Paladin Herald of the Sun 11.2 Class Set 2pc", ["text"] = "Vergeltung\nHeilung und Schaden von 'Morgenlicht' sind um 30% erhöht und Ihr erhaltet 'Solarzorn', nachdem 'Zornige Vergeltung' ausläuft, was den Effekt von 'Avatar der Sonne' zusätzliche [10][10] Sek. anhalten lässt.\n\nSchutz\nHeilung und Schaden von 'Morgenlicht' sind um 30% erhöht und Ihr erhaltet 'Solarzorn', nachdem 'Zornige Vergeltung' ausläuft, was den Effekt von 'Avatar der Sonne' zusätzliche [10][10] Sek. anhalten lässt.\n\nHeilig (Zornige Vergeltung)\nHeilung und Schaden von 'Morgenlicht' sind um 60% erhöht und Ihr erhaltet 'Solarzorn', nachdem 'Zornige Vergeltung' ausläuft, was den Effekt von 'Avatar der Sonne' zusätzliche 10[10][10] Sek. anhalten lässt." }
entries[1236384] = { ["name"] = "Paladin Herald of the Sun 11.2 Class Set 4pc", ["text"] = "Vergeltung\nDer Einsatz von 'Solarzorn' erhöht die Effektivität Eurer Heilige Kraft verbrauchenden Fähigkeiten um 15% und verleiht Euch [2][2]-mal 'Morgenlicht'.\n\nSchutz\nDer Einsatz von 'Solarzorn' erhöht die Effektivität Eurer Heilige Kraft verbrauchenden Fähigkeiten um 15% und verleiht Euch [2][2]-mal 'Morgenlicht'.\n\nHeilig (Zornige Vergeltung)\nDer Einsatz von 'Solarzorn' erhöht die Effektivität Eurer Heilige Kraft verbrauchenden Fähigkeiten um 30% und verleiht Euch 2[2][2]-mal 'Morgenlicht'." }
entries[1236385] = { ["name"] = "Seelenbombardement" }
entries[1236389] = { ["name"] = "Paladin Lightsmith 11.2 Class Set 2pc", ["text"] = "Schutz\nDer Schaden von 'Hammer und Amboss' ist um 15% erhöht und kann außerdem durch mit 40% Effektivität ausgelöst werden.\n\nVergeltung\nDie Heilung von 'Hammer und Amboss' ist um 15% erhöht und kann außerdem durch 'Kreuzfahrerstoß' mit 40% Effektivität ausgelöst werden.\n\nHeilig\nDie Heilung von 'Hammer und Amboss' ist um 15% erhöht und kann außerdem durch 'Kreuzfahrerstoß' mit 75% Effektivität ausgelöst werden.\n\n(750ms Abklingzeit)" }
entries[1236390] = { ["name"] = "Paladin Lightsmith 11.2 Class Set 4pc", ["text"] = "Der Einsatz von 'Hammer und Amboss' generiert außerdem einen Stapel von 'Meisterwerk', wodurch Euer nächster Einsatz von 'Heilige Bewaffnung' pro Stapel zusätzlich eine geringere Version von sich selbst auf einen Verbündeten in der Nähe wirkt." }
entries[1236391] = { ["name"] = "Paladin Templar 11.2 Class Set 2pc", ["text"] = "Euer 'Himmelshammer' verursacht 20% mehr kritischen Trefferschaden und seine kritischen Treffer haben eine Chance von 50%, einen zusätzlichen Stapel von 'Errettung des Lichts' zu generieren.\n(Procchance: 50%)" }
entries[1236392] = { ["name"] = "Paladin Templar 11.2 Class Set 4pc", ["text"] = "Vergeltung\nEuer Einsatz von 'Hammer des Lichts' verursacht 35% erhöhten Schaden gegen das Primärziel, trifft 3 zusätzliche Ziele und kann nach 'Aschewelle' 1-mal öfter eingesetzt werden.\n\nHeilig, Schutz\nEuer Einsatz von 'Hammer des Lichts' verursacht 35% erhöhten Schaden gegen das Primärziel, trifft 3 zusätzliche Ziele und kann nach 'Auge von Tyr' 1-mal öfter eingesetzt werden." }
entries[1236394] = { ["name"] = "Priest Oracle 11.2 Class Set 2pc", ["text"] = "Heilig, Schatten\nDer Einsatz von 'Gebet der Heilung' heilt Euer Ziel um (1400% der Zaubermacht).\n\nDisziplin\nDer erste Blitz jedes Einsatzes von 'Sühne' verursacht 200% mehr Schaden oder Heilung." }
entries[1236395] = { ["name"] = "Priest Oracle 11.2 Class Set 4pc", ["text"] = "Der Einsatz von 'Vorahnung der Frömmigkeit' oder 'Vorahnung des Trostes' generiert 2 Stapel von 'Vorahnung der Einsicht mit 100% Effektivität. Wenn ein Stapel von 'Vorahnung der Einsicht' verbraucht wird, erhöht das Euer Tempo 10 Sek. lang um 1.0%. Mehrere Anwendungen können sich überlappen." }
entries[1236396] = { ["name"] = "Priest Voidweaver 11.2 Class Set 2pc", ["text"] = "Heilig\nDer Einsatz von 'Leerenschlag' ist um 30% erhöht und die Zauberzeit von 'Leerenschlag' ist um 20% reduziert.\n\nSchatten\nDer Einsatz von 'Leerenschlag' ist um 30% erhöht und die Zauberzeit von 'Leerenschlag' ist um 20% reduziert. Die Abklingzeit von 'Leerenschlag' ist um 50% reduziert.\n\nDisziplin\nDer Einsatz von 'Leerenschlag' und 'Sühne' ist um 30% erhöht und die Zauberzeit von 'Leerenschlag' ist um 20% reduziert." }
entries[1236397] = { ["name"] = "Priest Voidweaver 11.2 Class Set 4pc", ["text"] = "Disziplin\nDer Einsatz von 'Leerenschlag' vergrößert jetzt 'Entropischer Riss', der Einsatz von 'Kollabierende Leere' erhöht den Schaden von 'Entropischer Riss' um weitere 10% und den Schaden Eures nächsten Einsatzes von 'Gedankenschlag' ist basierend auf der Größe des entropischen Risses zum Zeitpunkt des Zusammenbruchs um 200% erhöht.\n\nHeilig, Schatten\nDer Einsatz von 'Leerenschlag' vergrößert jetzt 'Entropischer Riss', der Einsatz von 'Kollabierende Leere' erhöht den Schaden von 'Entropischer Riss' um weitere 10% und den Schaden Eures nächsten Einsatzes von 'Leerenstrom' ist basierend auf der Größe des entropischen Risses zum Zeitpunkt des Zusammenbruchs um 200% erhöht." }
entries[1236398] = { ["name"] = "Priest Archon 11.2 Class Set 2pc", ["text"] = "Schatten\nStrahlenkränze erzeugen zusätzlich 10 Wahnsinn im Verlauf von 5 Sek. und 'Resonanzenergie' erhöht den Schaden von 'Verschlingende Seuche' um 5.0%.\n\nDisziplin, Heilig\nStrahlenkränze reduzieren die Abklingzeit von 'Segenswort: Epiphanie' und 'Segenswort: Heiligung' um 5 Sek. und 'Resonanzenergie' erhöht die Heilung Eurer Segensworte um 5.0%." }
entries[1236399] = { ["name"] = "Priest Archon 11.2 Class Set 4pc", ["text"] = "Heilig\nWährend 'Kraftwoge' aktiv ist, wird dem Effekt alle 2 Einsätze von 'Segenswort: Epiphanie' oder 'Segenswort: Heiligung' ein weiterer Strahlenkranz mit 100% Effektivität hinzugefügt. Kann bis zu 2-mal auftreten.\n\nDisziplin, Schatten\nWährend 'Kraftwoge' aktiv ist, wird dem Effekt alle 2 Einsätze von 'Verschlingende Seuche' ein weiterer Strahlenkranz mit 100% Effektivität hinzugefügt. Kann bis zu 2-mal auftreten." }
entries[1236400] = { ["name"] = "Rogue Deathstalker 11.2 Class Set 2pc", ["text"] = "Gesetzlosigkeit, Täuschung\nDer Einsatz von 'Symbole des Todes' erhöht während der aktiven Dauer die Effektivität aller Schadenseffekte und Schadensboni von 'Todespirscher' um 40%.\n\nMeucheln\nDer Einsatz von 'Tückische Klinge' erhöht während der aktiven Dauer die Effektivität aller Schadenseffekte und Schadensboni von 'Todespirscher' um 60%." }
entries[1236401] = { ["name"] = "Rogue Deathstalker 11.2 Class Set 4pc", ["text"] = "Gesetzlosigkeit, Täuschung\nDer Einsatz von 'Symbole des Todes' erhöht während der aktiven Dauer die Effektivität aller Schadenseffekte und Schadensboni von 'Todespirscher' um 40%.\n\nMeucheln\nDer Einsatz von 'Tückische Klinge' erhöht während der aktiven Dauer die Effektivität aller Schadenseffekte und Schadensboni von 'Todespirscher' um 60%." }
entries[1236402] = { ["name"] = "Rogue Fatebound 11.2 Class Set 2pc", ["text"] = "Gesetzlosigkeit\nDer Einsatz von 'Geisterhafter Schlag' verursacht 50% mehr Schaden und hält 4 Sek. länger an.\n\nBei 'Grenzfall' eine zusätzliche 'Schicksalsgebundene Münze' geworfen und der Einsatz von 'Geisterhafter Schlag' löst deren Effekt aus.\n\nMeucheln, Täuschung\nDer Einsatz von 'Königsmord' verursacht 10% mehr Schaden und hält 4 Sek. länger an.\n\nBei 'Grenzfall' eine zusätzliche 'Schicksalsgebundene Münze' geworfen und der Einsatz von 'Königsmord' löst deren Effekt aus." }
entries[1236403] = { ["name"] = "Rogue Fatebound 11.2 Class Set 4pc", ["text"] = "Gesetzlosigkeit\nWenn Ihr eine 'Schicksalsgebundene Münze' besitzt, ist die Abklingzeit von 'Adrenalinrausch' um 30.0 Sek. und von 'Geisterhafter Schlag' um 15.0 Sek. reduziert.\n\nMeucheln, Täuschung\nWenn Ihr eine 'Schicksalsgebundene Münze' besitzt, ist die Abklingzeit von 'Todesmal' um 30.0 Sek. und von 'Königsmord' um 15.0 Sek. reduziert." }
entries[1236404] = { ["name"] = "Rogue Trickster 11.2 Class Set 2pc", ["text"] = "Der Einsatz von 'Ungesehene Klinge' verursacht 35% mehr Schaden und hat eine Chance von 35%, zweimal zuzuschlagen." }
entries[1236405] = { ["name"] = "Rogue Trickster 11.2 Class Set 4pc", ["text"] = "Ihr könnt 'Gnadenstoß' jetzt ein zweites Mal innerhalb von 5 Sek. einsetzen und 150% des normalen Schadens verursachen." }
entries[1236406] = { ["name"] = "Shaman Farseer 11.2 Class Set 2pc", ["text"] = "Der Einsatz von 'Schnelligkeit der Ahnen' beschwört einen ermächtigten Ahnen für 15 Sek., der 10% mehr Schaden und Heilung verursacht." }
entries[1236407] = { ["name"] = "Shaman Farseer 11.2 Class Set 4pc", ["text"] = "Elementar, Verstärkung\nDer Einsatz von 'Schnelligkeit der Ahnen' erhöht den Schaden und die Heilung Eurer Zauber um 25%, verringert die Manakosten Eurer Zauber um 25% und erhöht die Aufladerate von 'Lavaeruption' 8 Sek. lang um 50%.\n\nWiederherstellung\nDer Einsatz von 'Schnelligkeit der Ahnen' erhöht den Schaden und die Heilung Eurer Zauber um 25%, verringert die Manakosten Eurer Zauber um 25% und erhöht die Aufladerate von 'Lavaeruption' und 'Springflut' 8 Sek. lang um 50%." }
entries[1236408] = { ["name"] = "Shaman Stormbringer 11.2 Class Set 2pc", ["text"] = "Verstärkung, Wiederherstellung\nDer Einsatz von 'Aszendenz' hat eine Chance von 100%, eine Ladung von 'Sturmgewitter' zu generieren und jeder 8. Einsatz von 'Erwachende Stürme' aktiviert 'Aszendenz' für 6.0 Sek.\n\nElementar\nDer Einsatz von 'Aszendenz' hat eine Chance von 100%, eine Ladung von 'Sturmgewitter' zu generieren und jeder 9. Einsatz von 'Erwachende Stürme' aktiviert 'Aszendenz' für 6.0 Sek.\n\n(100ms Abklingzeit)" }
entries[1236409] = { ["name"] = "Shaman Stormbringer 11.2 Class Set 4pc", ["text"] = "Elementar, Wiederherstellung\nEuer Naturschaden ist um 3.0% erhöht und während 'Aszendenz' aktiv ist, lassen Eure nächsten Einsätze von 'Sturmgewitter' 2-mal einen Sturm aufziehen, der nach 1.5 Sek. dem Primärziel (960% der Zaubermacht) Naturschaden und Gegnern in der Nähe verringerten Schaden zufügt.\n\nVerstärkung\nEuer Naturschaden ist um 5.0% erhöht und während 'Aszendenz' aktiv ist, lassen Eure nächsten Einsätze von 'Sturmgewitter' 2-mal einen Sturm aufziehen, der nach 1.5 Sek. dem Primärziel (400% der Angriffskraft) Naturschaden und Gegnern in der Nähe verringerten Schaden zufügt.\n\n(100ms Abklingzeit)" }
entries[1236410] = { ["name"] = "Shaman Totemic 11.2 Class Set 2pc", ["text"] = "Verstärkung\nNachdem Ihr alle Partikel von 'Wirbelnde Elemente' verbraucht habt, wirkt Euer 'Wogendes Totem' 'Urzeitlicher Sturm' mit 200% Effektivität an [seinem Standort] [dem Standort Eurer Fähigkeit 'Wogendes Totem' ].\n\nElementar, Wiederherstellung\nNachdem Ihr alle Partikel von 'Wirbelnde Elemente' verbraucht habt, wirkt Ihr 'Platzregen' mit 200% Effektivität an [seinem Standort] [dem Standort Eurer Fähigkeit 'Wogendes Totem' ]." }
entries[1236411] = { ["name"] = "Shaman Totemic 11.2 Class Set 4pc", ["text"] = "Elementar, Wiederherstellung\nNachdem Ihr 'Platzregen' eingesetzt habt, wird Eure nächste 'Kettenheilung', 'Heilende Woge' oder 'Welle der Heilung' mit 150% Effektivität erneut ausgelöst.\n\nVerstärkung\nNachdem Ihr 'Urzeitlicher Sturm' eingesetzt habt, wird Eure nächste 'Lavapeitsche' oder 'Feuernova' mit 150% Effektivität erneut ausgelöst.\n\n(500ms Abklingzeit)" }
entries[1236412] = { ["name"] = "Schneefeld" }
entries[1236413] = { ["name"] = "Warlock Hellcaller 11.2 Class Set 2pc", ["text"] = "Dämonologie, Zerstörung\nDer Einsatz von 'Mal von Xavius' erhöht den Schaden von 'Geschwärzte Seele' um weitere 3% pro Stapel. Der Einsatz von 'Böswilligkeit' erhöht die Anzahl der Stapel von 'Welken' um weitere 2.\n\nGebrechen\nDer Einsatz von 'Mal von Xavius' erhöht den Schaden von 'Geschwärzte Seele' um weitere 6% pro Stapel. Der Einsatz von 'Böswilligkeit' erhöht die Anzahl der Stapel von 'Welken' um weitere 2." }
entries[1236414] = { ["name"] = "Warlock Hellcaller 11.2 Class Set 4pc", ["text"] = "Gebrechen\nDer Einsatz von 'Böswilligkeit' erzeugt 2 Stapel von 'Gequältes Crescendo' und verhindert, dass 'Geschwärzte Seele' Stapel verbraucht und 8 Sek. lang 25% schneller Schaden verursacht.\n\nDämonologie, Zerstörung\nDer Einsatz von 'Böswilligkeit' erzeugt 2 Stapel von 'Pyrolyse' und verhindert, dass 'Geschwärzte Seele' Stapel verbraucht und 8 Sek. lang 15% schneller Schaden verursacht." }
entries[1236415] = { ["name"] = "Warlock Soul Harvester 11.2 Class Set 2pc", ["text"] = "Der Einsatz von 'Schatten des Todes' entfesselt Eure 'Dämonenseele' 9 Sek. lang gegen Euer aktuelles Ziel, was dem Ziel (279.306% der Zaubermacht) Schattenschaden und Gegnern innerhalb von 10 Metern (186.209% der Zaubermacht) Schattenschaden zufügt." }
entries[1236416] = { ["name"] = "Warlock Soul Harvester 11.2 Class Set 4pc", ["text"] = "Der Schaden von 'Dämonenseele' ist um 45% und der Schaden von 'Tückischer Schnitter' um 45% erhöht. Eure 'Dämonenseele' generiert alle 3 Sek. 1 Seelensplitter, während Gegner angegriffen werden." }
entries[1236417] = { ["name"] = "Warlock Diabolist 11.2 Class Set 2pc", ["text"] = "Dämonologie\n'Hand von Gul'dan' wird mit voller Macht gewirkt beschwört bis zu 3 dämonische Augen. Wenn 'Dämonische Kunst' verbraucht wird, werden Eure dämonischen Augen auf Euer aktuelles Ziel geschleudert, fügen ihm mit einer Explosion (502.813% der Zaubermacht) Feuerschaden und Gegnern innerhalb von 10 Metern zusätzlich (335.172% der Zaubermacht) Feuerschaden zu.\n\nGebrechen, Zerstörung\nDer Einsatz von 'Chaosblitz', 'Feuerregen' oder 'Schattenbrand' beschwört bis zu 3 dämonische Augen. Wenn 'Dämonische Kunst' verbraucht wird, werden Eure dämonischen Augen auf Euer aktuelles Ziel geschleudert, fügen ihm mit einer Explosion (502.813% der Zaubermacht) Feuerschaden und Gegnern innerhalb von 10 Metern zusätzlich (335.172% der Zaubermacht) Feuerschaden zu." }
entries[1236418] = { ["name"] = "Warlock Diabolist 11.2 Class Set 4pc", ["text"] = "Dämonische Augen analysieren den Kampf, während sie aktiv sind und liefern Euch Informationen, wenn sie explodieren, was Eure Intelligenz 10 Sek. lang um 2% erhöht." }
entries[1236419] = { ["name"] = "Warrior Colossus 11.2 Class Set 2pc", ["text"] = "Der Schaden von 'Demolieren' ist um 20% erhöht und der kritische Trefferschaden Eurer Fähigkeiten ist gegen Ziele, die von Eurem 'Demolieren' betroffen sind, ist basierend auf der Anzahl Eurer Stapel von 'Kolossale Macht' 10 Sek. lang um bis zu 20% erhöht." }
entries[1236420] = { ["name"] = "Warrior Colossus 11.2 Class Set 4pc", ["text"] = "Furor, Schutz\nDer Einsatz von 'Demolieren' erhöht die kritische Trefferchance Eurer nächsten 1 Einsätze von [Quellwert]'Schildschlag' um 100%. Kritische Treffer von 'Schildschlag' erhöhen den Schaden von 'Verwunden' und 'Tiefe Wunden' 8 Sek. lang um 80%.\n\nWaffen\nDer Einsatz von 'Demolieren' erhöht die kritische Trefferchance Eurer nächsten 1 Einsätze von [Quellwert]'Tödlicher Stoß' um 100%. Kritische Treffer von 'Tödlicher Stoß' erhöhen den Schaden von 'Verwunden' und 'Tiefe Wunden' 8 Sek. lang um 80%.", ["unresolvedValues"] = true }
entries[1236421] = { ["name"] = "Warrior Mountain Thane 11.2 Class Set 2pc", ["text"] = "Eure 'Donnerexplosion' hat eine Chance von 35%, 5-mal 'Ionisierender Schlag' gegen betroffene Ziele auszulösen. Jeder Schlag verursacht (150% der Angriffskraft) Naturschaden." }
entries[1236422] = { ["name"] = "Warrior Mountain Thane 11.2 Class Set 4pc", ["text"] = "Euer 'Ionisierender Schlag' verursacht 100% mehr Schaden. Zusätzlich erhaltet Ihr beim Auslösen von 'Ionisierender Schlag' eine Ladung von 'Donnerexplosion‘, und Eure nächste 'Donnerexplosion' verursacht 100% mehr Schaden." }
entries[1236423] = { ["name"] = "Warrior Slayer 11.2 Class Set 2pc", ["text"] = "Der Schaden von 'Hinrichten' ist um 10% erhöht und Eure Hinrichtungen von 'Plötzlicher Tod' haben eine Chance von 10% pro Stapel von 'Überwältigt' auf dem Ziel, einen 'Schlächterschlag' mit 100% Effektivität auszulösen." }
entries[1236424] = { ["name"] = "Warrior Slayer 11.2 Class Set 4pc", ["text"] = "Furor, Schutz\nDer Schaden von 'Wütender Schlag' ist um 10% erhöht und 'Wütender Schlag' hat eine Chance von 2% pro Stapel, das Ziel zu überwältigen und 'Sturm ernten' mit 150% Effektivität auszulösen.\n\nWaffen\nDer Schaden von 'Überwältigen' ist um 10% erhöht und 'Überwältigen' hat eine Chance von 2% pro Stapel, das Ziel zu überwältigen und 'Sturm ernten' mit 150% Effektivität auszulösen.\n\n(500ms Abklingzeit)" }
