entries[1236428] = { ["name"] = "Seht!", ["text"] = "100 Meter Reichweite\nWirken in 3 sek.\nDer Zaubernde beschwört einen Schwarm Augen, die jeweils einen Laserstrahl abfeuern und Spielercharakteren vor sich so 30 Schattenschaden zufügen." }
