entries[1236512] = { ["name"] = "Instabile Anima", ["text"] = "100 Meter Reichweite\nSofort\nHochadjudikatorin Aleez entfesselt ' Instabile Anima ' auf 2 Spielercharaktere, das 14 Sek. lang alle 2 Sek. 1697115 Schattenschaden verursacht.\n\nVon ' Instabile Anima ' betroffene Spielercharaktere fügen Verbündeten innerhalb von 5 Metern 14 Sek. lang alle 2 Sek. 1697115 Schattenschaden zu." }
entries[1236513] = { ["name"] = "Instabile Anima", ["text"] = "Unbegrenzte Reichweite\nSofort\nHochadjudikatorin Aleez entfesselt ' Instabile Anima ' auf 2 Spielercharaktere, das 14 Sek. lang alle 2 Sek. 1697115 Schattenschaden verursacht.\n\nVon ' Instabile Anima ' betroffene Spielercharaktere fügen Verbündeten innerhalb von 5 Metern 14 Sek. lang alle 2 Sek. 1697115 Schattenschaden zu." }
