entries[1236556] = { ["name"] = "Dryade", ["text"] = "100 Meter Reichweite\nSofort\nGleichgewicht, Wildheit, Wächter\nDer Einsatz von 'Himmlische Ausrichtung' erbittet für 10 Sek. die Unterstützung einer Dryade, die 'Sternensog' mit 360% Effektivität' und 'Sternenregen' mit 800% Effektivität wirkt.\n\nWiederherstellung\nDer Einsatz von 'Inkarnation: Baum des Lebens' oder 'Konvokation der Geister' erbittet für 5 Sek. die Unterstützung einer Dryade, die 'Gelassenheit' mit 50% Effektivität wirkt und Euren Verbündeten mit der niedrigsten Gesundheit sofort mit 200% Effektivität 'Nachwachsen' lässt." }
