entries[1236573] = { ["name"] = "Gelassenheit", ["text"] = "40 Meter Reichweite\nSofort\nHeilt alle Verbündeten innerhalb von 40 Metern im Verlauf von 5 Sek. um [5 * (542.8% der Zaubermacht)] Gesundheit. Jede Heilung heilt das Ziel zusätzlich im Verlauf von 8 Sek. um (23.736% der Zaubermacht) Gesundheit. Dieser Effekt ist stapelbar.\n\nHeilung bei Zielen über 5 Ziele hinaus verringert." }
entries[1236574] = { ["name"] = "Gelassenheit", ["text"] = "Kanalisiert (Wirken in 5 sek.)\nHeilt alle Verbündeten innerhalb von 40 Metern im Verlauf von 5 Sek. um [(135.7% der Zaubermacht) * 5] Gesundheit. Jede Heilung heilt das Ziel zusätzlich im Verlauf von 8 Sek. um (23.736% der Zaubermacht) Gesundheit. Dieser Effekt ist stapelbar.\n\nHeilung bei Zielen über 5 Ziele hinaus verringert." }
