entries[1236586] = { ["name"] = "Gefräßiger Ausbruch", ["text"] = "Sofort\nDer Zaubernde stößt eine erbrochene Explosion aus, die Spielercharakteren innerhalb 15 Metern 65 körperlichen Schaden zufügt und sie zurückstößt.\n\nAußerdem fliegt toxischer Speichel in alle Richtungen, der Spielercharakteren innerhalb von 5 Metern 35 Schattenschaden zufügt und 1 Min. lang ' Verdauender Speichel ' hinterlässt." }
entries[1236600] = { ["name"] = "Arkane Wiederherstellung", ["text"] = "100 Meter Reichweite\nSofort\nWebt für 10 Sek. einen arkanen Kokon um Euch selbst und vier Verbündete in der Nähe, der den erlittenen Schaden um 75% verringert, bis 10915 Schaden abgewandt wurde.\n\nWenn ein Kokon ausläuft, explodiert er und heilt einen Verbündeten in der Nähe um 50% seiner verbleibenden Kraft." }
entries[1236607] = { ["name"] = "Sternenregen", ["text"] = "100 Meter Reichweite\nSofort\nRuft Wellen fallender Sterne auf Gegner innerhalb von 40 Metern herab, die Gegnern im Verlauf von 10 Sek. [(179.2% der Zaubermacht) * 11] Astralschaden zufügen." }
