entries[1236614] = { ["name"] = "Machtdemonstration", ["text"] = "300 Meter Reichweite\nWirken in 2 sek.\nInquisitor Sigar verabreicht Spielercharakteren Anima. Verursacht alle 1 Sek. 727335 Schattenschaden und erhöht sämtlichen Schaden und sämtliche Heilung 15 Sek. lang um 30%. Bei Ablauf bestraft Inquisitor Sigar Spielercharaktere für deren angeberische ' Machtdemonstration ' und fügt jedem Spielercharakter sowie deren Verbündeten innerhalb von 5 Metern 2424449 Schattenschaden zu." }
