entries[1236638] = { ["name"] = "Gefräßiger Ausbruch", ["text"] = "150 Meter Reichweite\nSofort\nAzhiccar speit Magensäure auf anvisierte Spielercharaktere und fügt Gegnern innerhalb von 10 Metern um den Einschlag 6 Sek. lang alle 1 Sek. 1212225 Schattenschaden zu. An ihrer Stelle hinterlässt er eine Lache ' Verdauender Speichel '." }
entries[1236640] = { ["name"] = "Sternensog", ["text"] = "40 Meter Reichweite\nWirken in 2 sek.\nEin Sog stellarer Energien fügt dem Ziel (1065.6% der Zaubermacht) Astralschaden zu." }
entries[1236643] = { ["name"] = "Verdauender Speichel", ["text"] = "150 Meter Reichweite\nSofort\nDer Zaubernde stößt eine erbrochene Explosion aus, die Spielercharakteren innerhalb 15 Metern 65 körperlichen Schaden zufügt und sie zurückstößt.\n\nAußerdem fliegt toxischer Speichel in alle Richtungen, der Spielercharakteren innerhalb von 5 Metern 35 Schattenschaden zufügt und 1 Min. lang ' Verdauender Speichel ' hinterlässt." }
entries[1236644] = { ["name"] = "Gabe von Elune", ["text"] = "Sofort\nTierherrschaft, Überleben\nErhöht den Schaden von 'Lauffeuerbombe' um 10%. Wenn 'Lunarsturm' abklingt, erhaltet Ihr eine 'Gabe von Elune', wodurch Ihr mit 'Lauffeuerbombe'[Quellwert] 2-mal um 150 erhöhten anfänglichen Schaden als Arkanschaden verursacht.\n\nTreffsicherheit\nErhöht den Schaden von 'Schnellfeuer' um 25%. Wenn 'Lunarsturm' abklingt, erhaltet Ihr eine 'Gabe von Elune', wodurch Ihr mit 'Gezielter Schuss'[Quellwert] 2-mal um 10 erhöhten Schaden als Arkanschaden verursacht.\n\n(300ms Abklingzeit)", ["unresolvedValues"] = true }
