entries[1236748] = { ["name"] = "Paladin Templar 11.2 Class Set 4pc Driver", ["text"] = "Sofort\nVergeltung\nEuer Einsatz von 'Hammer des Lichts' verursacht 0% erhöhten Schaden gegen das Primärziel, trifft 0 zusätzliche Ziele und kann nach 'Aschewelle' 0-mal öfter eingesetzt werden.\n\nHeilig, Schutz\nEuer Einsatz von 'Hammer des Lichts' verursacht 0% erhöhten Schaden gegen das Primärziel, trifft 0 zusätzliche Ziele und kann nach 'Auge von Tyr' 0-mal öfter eingesetzt werden." }
entries[1236759] = { ["name"] = "Überinfusionssprengung", ["text"] = "Unbegrenzte Reichweite\nSofort\nLoom'ithar fügt während der Absorption arkaner Energie allen Spielercharakteren 8 Sek. lang alle 0.5 Sek. 266671 Arkanschaden zu. Anschließend entlädt es die gesammelte Energie in einer gewaltigen Explosion, die Spielercharakteren innerhalb von 45 Metern 129345416 Arkanschaden zufügt." }
entries[1236761] = { ["name"] = "Verschlingen", ["text"] = "150 Meter Reichweite\nSofort\nBei Erreichen von 100 Energie atmet Azhiccar tief ein und versucht 18 Sek. lang, alle Spielercharaktere und Kreaturen in der Arena zu verschlingen, wobei er allen Spielercharakteren alle 1 Sek. 606112 Schattenschaden zufügt.\n\nJede verschlungene lebende Kreatur oder Spielercharakter wird für Azhiccar zum ' Festmahl '." }
