entries[1236784] = { ["name"] = "Brüchiger Nexus", ["text"] = "Sofort\nEine kristalline Wand aus Leerenenergie, die beim Aufprall auf einen von ' Kristalleinhüllung ' betroffenen Spielercharakter explodiert. Die Explosion verschießt ' Nexusschrapnell ' und belegt alle Spielercharaktere mit ' Kristallische Fleischwunden '." }
